import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target, MessageSquare, AlertOctagon, Calendar, ChevronDown, FileText, BarChart3, ScanFace, Command, Radar, Fingerprint } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'Terminal active. I am ready to audit your capital allocation. What is your directive?' 
            : 'Welcome back, Pilot. I\'m ready to help optimize your financial wellness. How can I assist today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "Signal lost. The neural core is currently unreachable. Please retry.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS FOR CLEANER RENDER ---

  const renderDailyReport = () => {
      if (!dailyReport) return null;
      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-start">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-emerald-500/20 rounded-lg"><Zap className="w-4 h-4 text-emerald-400" /></div>
                          <span className="text-xs font-black text-emerald-400 uppercase tracking-widest">Tactical Report</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Daily Ops</h3>
                      <p className="text-slate-400 text-sm font-medium mt-1">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                  </div>
                  <div className="text-right">
                      <div className="relative inline-flex items-center justify-center">
                          <svg className="w-20 h-20 transform -rotate-90">
                              <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-800" />
                              <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={226} strokeDashoffset={226 - (dailyReport.riskScore / 100) * 226} className={dailyReport.riskLevel === 'Critical' ? 'text-rose-500' : dailyReport.riskLevel === 'Warning' ? 'text-amber-400' : 'text-emerald-400'} />
                          </svg>
                          <span className="absolute text-xl font-black text-white">{dailyReport.riskScore.toFixed(0)}</span>
                      </div>
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">Risk Index</div>
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-5 bg-slate-900/40 rounded-2xl border border-white/5 hover:bg-slate-900/60 transition-colors group">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-slate-400">24h Burn Rate</div>
                      <div className="text-2xl font-mono font-bold text-white">{formatCurrency(dailyReport.totals.expense)}</div>
                  </div>
                  <div className="p-5 bg-slate-900/40 rounded-2xl border border-white/5 hover:bg-slate-900/60 transition-colors group">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-slate-400">Momentum</div>
                      <div className={`text-2xl font-mono font-bold ${dailyReport.metrics.momentumDelta > 0.1 ? 'text-rose-400' : 'text-emerald-400'}`}>
                          {dailyReport.metrics.momentumDelta > 0 ? '+' : ''}{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%
                      </div>
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Live Signals Detected</h4>
                  {dailyReport.signals.map((sig, idx) => (
                      <div key={idx} className={`flex gap-4 p-4 rounded-xl border backdrop-blur-sm ${sig.type === 'stable' ? 'bg-emerald-500/5 border-emerald-500/10' : 'bg-rose-500/5 border-rose-500/10'}`}>
                          <div className={`mt-1 ${sig.type === 'stable' ? 'text-emerald-400' : 'text-rose-400'}`}>
                              {sig.type === 'stable' ? <CheckCircle className="w-5 h-5" /> : <AlertOctagon className="w-5 h-5" />}
                          </div>
                          <div>
                              <div className="text-sm font-bold text-white mb-0.5">{sig.title}</div>
                              <div className="text-xs text-slate-400 leading-relaxed font-medium">{sig.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              <div className={`p-6 rounded-2xl border flex items-start gap-5 ${dailyReport.action.priority === 'high' ? 'bg-rose-950/30 border-rose-500/30' : 'bg-indigo-950/30 border-indigo-500/30'}`}>
                  <div className={`p-3 rounded-xl shrink-0 ${dailyReport.action.priority === 'high' ? 'bg-rose-500 text-white' : 'bg-indigo-500 text-white'}`}>
                      <Target className="w-5 h-5" />
                  </div>
                  <div>
                      <div className="text-[10px] font-black uppercase tracking-widest mb-1.5 opacity-70 flex items-center gap-2">
                          <span className={`w-2 h-2 rounded-full ${dailyReport.action.priority === 'high' ? 'bg-rose-500' : 'bg-indigo-400'} animate-pulse`}></span>
                          Recommended Action
                      </div>
                      <h4 className="text-base font-bold text-white mb-2">{dailyReport.action.text}</h4>
                      <div className="text-xs font-mono text-slate-300 opacity-80 bg-black/20 p-2 rounded inline-block">Effect: {dailyReport.action.effect}</div>
                  </div>
              </div>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-center">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-amber-500/20 rounded-lg"><Calendar className="w-4 h-4 text-amber-400" /></div>
                          <span className="text-xs font-black text-amber-400 uppercase tracking-widest">Strategic Report</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Monthly Audit</h3>
                      <p className="text-slate-400 text-sm font-medium mt-1">{monthlyReport.month}</p>
                  </div>
                  <div className={`px-4 py-2 bg-white/5 rounded-xl border border-white/10 text-center`}>
                      <div className="text-xs text-slate-500 font-black uppercase tracking-widest">Health Level</div>
                      <span className={`text-lg font-black ${monthlyReport.healthLevel === 'Critical' ? 'text-rose-500' : monthlyReport.healthLevel === 'Fragile' ? 'text-amber-400' : 'text-emerald-400'}`}>{monthlyReport.healthLevel}</span>
                  </div>
              </div>

              <div className="flex justify-center py-6">
                  <div className="relative w-48 h-48 flex items-center justify-center">
                      <div className="absolute inset-0 rounded-full border-[12px] border-slate-800"></div>
                      <div className={`absolute inset-0 rounded-full border-[12px] border-t-transparent border-l-transparent transform -rotate-45 transition-all duration-1000 ${monthlyReport.healthScore >= 80 ? 'border-emerald-500' : monthlyReport.healthScore >= 50 ? 'border-amber-500' : 'border-rose-500'}`} style={{ clipPath: `polygon(0 0, 100% 0, 100% ${monthlyReport.healthScore}%, 0 100%)`}}></div>
                      <div className="text-center z-10">
                          <div className="text-5xl font-black text-white tracking-tighter">{monthlyReport.healthScore.toFixed(0)}</div>
                          <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mt-1">Health Score</div>
                      </div>
                  </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Savings Rate</div>
                      <div className={`text-lg font-mono font-bold ${monthlyReport.metrics.savingsPowerIndex > 0.1 ? 'text-emerald-400' : 'text-rose-400'}`}>{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</div>
                  </div>
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Fixed Load</div>
                      <div className="text-lg font-mono font-bold text-white">{(monthlyReport.metrics.expenseLoadRatio * 100).toFixed(0)}%</div>
                  </div>
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Risk Factor</div>
                      <div className={`text-lg font-mono font-bold ${monthlyReport.riskScore > 50 ? 'text-rose-500' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</div>
                  </div>
              </div>

              <div className="bg-gradient-to-br from-indigo-900/20 to-violet-900/20 border border-indigo-500/20 rounded-2xl p-6 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity"><Crown className="w-16 h-16 text-indigo-400" /></div>
                  <h4 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-4 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Mission Objective</h4>
                  <div className="text-lg font-bold text-white mb-6 leading-tight">{monthlyReport.strategicPlan.objective}</div>
                  <div className="space-y-3">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
                          <div key={i} className="flex gap-4 items-start">
                              <span className="flex items-center justify-center w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 text-xs font-bold shrink-0 mt-0.5">{i+1}</span>
                              <span className="text-sm text-slate-300 font-medium">{act}</span>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="space-y-2">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Structural Diagnosis</h4>
                  {monthlyReport.problems.map((prob, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 rounded-xl bg-slate-900/30 border border-white/5">
                          <div className={`w-2 h-2 rounded-full ${prob.severity === 'high' ? 'bg-rose-500 animate-pulse' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                          <span className="text-xs font-medium text-slate-300">{prob.title}</span>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderAiAnalysis = () => {
      if (loading) {
          return (
              <div className="flex flex-col items-center justify-center h-full py-20 space-y-8 animate-fade-in">
                  <div className="relative">
                      <div className="w-16 h-16 bg-indigo-500/10 rounded-full flex items-center justify-center animate-ping absolute"></div>
                      <div className="w-16 h-16 bg-indigo-600 rounded-full flex items-center justify-center relative shadow-[0_0_30px_rgba(99,102,241,0.5)]">
                          <BrainCircuit className="w-8 h-8 text-white animate-pulse" />
                      </div>
                  </div>
                  <div className="text-center space-y-2">
                      <h3 className="text-lg font-bold text-white">Neural Audit Initialized</h3>
                      <p className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em] animate-pulse">Scanning Transaction Vectors...</p>
                  </div>
              </div>
          );
      }
      if (!analysis) return null;

      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-start">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-indigo-500/20 rounded-lg"><BrainCircuit className="w-4 h-4 text-indigo-400" /></div>
                          <span className="text-xs font-black text-indigo-400 uppercase tracking-widest">Deep Scan</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Neural Audit</h3>
                  </div>
                  <div className={`px-4 py-2 rounded-xl border text-xs font-bold ${analysis.risk_score > 50 ? 'bg-rose-500/10 border-rose-500/20 text-rose-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'}`}>
                      Risk Score: {Math.round(analysis.risk_score)}/100
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-6 bg-slate-900/40 rounded-2xl border border-white/5">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Predicted Burn (30d)</div>
                      <div className="text-3xl font-mono font-black text-white">{formatCurrency(analysis.predicted_spend_next_month)}</div>
                  </div>
                  <div className="p-6 bg-slate-900/40 rounded-2xl border border-white/5 flex items-center justify-center">
                      <div className="text-center">
                          <TrendingUp className="w-8 h-8 text-indigo-400 mx-auto mb-2" />
                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Trend Analysis</span>
                      </div>
                  </div>
              </div>

              <div className="space-y-4">
                  {analysis.insights.map((insight, idx) => (
                      <div key={idx} className={`p-5 rounded-2xl border flex gap-4 ${insight.type === 'critical' ? 'bg-rose-500/5 border-rose-500/20' : insight.type === 'warning' ? 'bg-amber-500/5 border-amber-500/20' : 'bg-slate-800/30 border-white/5'}`}>
                          <div className="mt-0.5 shrink-0 p-2 bg-black/20 rounded-lg h-fit">
                              {insight.type === 'success' && <CheckCircle className="w-4 h-4 text-emerald-400" />}
                              {insight.type === 'warning' && <AlertTriangle className="w-4 h-4 text-amber-400" />}
                              {insight.type === 'critical' && <ShieldAlert className="w-4 h-4 text-rose-400" />}
                              {insight.type === 'info' && <Info className="w-4 h-4 text-blue-400" />}
                          </div>
                          <div>
                              <div className="text-sm font-bold text-white mb-1">{insight.title}</div>
                              <div className="text-xs text-slate-400 leading-relaxed font-medium">{insight.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-gradient-to-br from-indigo-950/40 to-slate-900 border border-indigo-500/20 p-6 rounded-2xl relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 blur-[50px]"></div>
                      <h3 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-4 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Optimization</h3>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-4 relative z-10">
                              <div className="flex justify-between items-start">
                                  <div>
                                      <div className="text-base font-bold text-white">{proposal.title}</div>
                                      <div className="text-xs text-slate-400 mt-1 max-w-sm">{proposal.reason_simple}</div>
                                  </div>
                                  <div className="text-right">
                                      <div className="text-lg font-black text-white font-mono">{formatCurrency(proposal.target_amount)}</div>
                                      <div className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">Potential Impact</div>
                                  </div>
                              </div>
                              <div className="flex gap-3 pt-2">
                                  <button onClick={() => setShowRejectModal(proposal)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-400 font-bold text-[10px] uppercase tracking-widest rounded-xl transition-colors border border-white/5">Dismiss</button>
                                  <button onClick={() => handleAcceptProposal(proposal)} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-[10px] uppercase tracking-widest rounded-xl transition-colors shadow-lg shadow-indigo-600/20 flex items-center gap-2">
                                      <Check className="w-3 h-3" /> Execute Protocol
                                  </button>
                              </div>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      );
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-md rounded-[3rem] border border-white/10">
            <div className="text-center p-10 max-w-md animate-slide-up bg-[#0f172a] rounded-[2rem] border border-white/10 shadow-2xl">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-600 to-purple-600 flex items-center justify-center mx-auto mb-6 shadow-2xl ring-4 ring-white/10"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Access Restricted</h2>
                <p className="text-slate-400 mb-8 text-sm font-medium leading-relaxed">Your neural quota of {currentLimit} operations has been exhausted. Upgrade to Elite to unlock unlimited intelligence.</p>
                <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-950 font-black rounded-xl shadow-xl hover:scale-105 active:scale-95 transition-all text-sm uppercase tracking-widest">Upgrade Terminal</button>
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 h-full transition-all duration-500 ${isLocked ? 'blur-sm opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>

        {/* LEFT COLUMN: COMMAND CENTER */}
        <div className="lg:col-span-7 flex flex-col gap-8 overflow-hidden h-full">

            {/* Header Area */}
            <div className="flex items-center justify-between shrink-0">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tighter">
                        <ScanFace className="w-8 h-8 text-indigo-500" />
                        Financial Intelligence
                    </h2>
                    <p className="text-slate-400 text-xs mt-1 font-bold uppercase tracking-widest pl-1">Neural Analysis & Tactical Reporting</p>
                </div>
                <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    <Fingerprint className="w-3 h-3" />
                    Token Usage: {insightUsage}/{currentLimit}
                </div>
            </div>

            {/* PROTOCOL CHIPS (Command Grid) */}
            <div className="grid grid-cols-3 gap-4 shrink-0">
                <button 
                    onClick={runAnalysis} 
                    disabled={loading}
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'ai' ? 'ring-2 ring-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'ai' ? 'from-indigo-600 to-indigo-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'ai' ? 'bg-indigo-500 text-white shadow-lg' : 'bg-slate-800 text-indigo-400 group-hover:bg-indigo-500 group-hover:text-white'}`}>
                            {loading ? <RefreshCw className="w-6 h-6 animate-spin" /> : <BrainCircuit className="w-6 h-6" />}
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'ai' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Deep Scan</span>
                    </div>
                </button>

                <button 
                    onClick={handleGenerateDaily} 
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'daily' ? 'ring-2 ring-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'daily' ? 'from-emerald-600 to-emerald-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'daily' ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-800 text-emerald-400 group-hover:bg-emerald-500 group-hover:text-white'}`}>
                            <Zap className="w-6 h-6" />
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'daily' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Daily Ops</span>
                    </div>
                </button>

                <button 
                    onClick={handleGenerateMonthly} 
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'monthly' ? 'ring-2 ring-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'monthly' ? 'from-amber-600 to-amber-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'monthly' ? 'bg-amber-500 text-white shadow-lg' : 'bg-slate-800 text-amber-400 group-hover:bg-amber-500 group-hover:text-white'}`}>
                            <Calendar className="w-6 h-6" />
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'monthly' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Monthly Strat</span>
                    </div>
                </button>
            </div>

            {/* CONTENT VIEWPORT */}
            <div className="flex-1 bg-slate-900/30 border border-white/5 rounded-[2.5rem] p-8 overflow-y-auto custom-scrollbar relative shadow-inner">
                {activeView === 'idle' && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-60">
                        <div className="w-24 h-24 bg-slate-900 rounded-full flex items-center justify-center mb-8 border border-white/5 shadow-2xl relative">
                            <div className="absolute inset-0 border-2 border-indigo-500/20 rounded-full animate-ping"></div>
                            <Radar className="w-10 h-10 text-indigo-500" />
                        </div>
                        <h3 className="text-xl font-bold text-white mb-2 uppercase tracking-tight">Awaiting Directive</h3>
                        <p className="text-slate-500 text-sm max-w-xs font-medium">Initialize a protocol from the command grid above to begin analysis.</p>
                    </div>
                )}

                {activeView === 'ai' && renderAiAnalysis()}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
            </div>
        </div>

        {/* RIGHT COLUMN: NEURAL LINK (CHAT) */}
        <div className="lg:col-span-5 flex flex-col h-full bg-[#0f172a] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl relative">
            {/* Header */}
            <div className="p-6 border-b border-white/5 bg-slate-900/50 backdrop-blur-md z-10 flex justify-between items-center">
                <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-purple-600'}`}>
                        {botMode === 'ruthless' ? <Terminal className="w-5 h-5 text-slate-300" /> : <Bot className="w-5 h-5 text-white" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Neural Link</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <div className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'} animate-pulse`}></div>
                            <p className="text-[9px] text-slate-400 font-black uppercase tracking-wider">{botMode === 'ruthless' ? 'Ruthless Logic' : 'Supportive Mode'}</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-900/10 via-transparent to-transparent">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                        <div className={`flex gap-3 max-w-[90%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 border shadow-sm mt-1 ${msg.role === 'user' ? 'bg-slate-800 border-white/10' : 'bg-indigo-600 border-indigo-500 text-white'}`}>
                                {msg.role === 'user' ? <User className="w-4 h-4 text-slate-400" /> : <Bot className="w-4 h-4" />}
                            </div>
                            <div>
                                <div className={`p-4 text-xs font-medium leading-relaxed shadow-lg rounded-2xl border ${msg.role === 'user' ? 'bg-indigo-900/20 text-indigo-100 rounded-tr-none border-indigo-500/20' : 'bg-slate-900/80 backdrop-blur-md text-slate-200 rounded-tl-none border-white/5'}`}>
                                    {msg.content}
                                </div>
                                {msg.suggestedActions && msg.suggestedActions.length > 0 && (
                                    <div className="flex flex-wrap gap-2 mt-3">
                                        {msg.suggestedActions.map((action, idx) => (
                                            <button key={idx} onClick={() => handleActionClick(action)} className="flex items-center gap-1.5 px-3 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 text-indigo-300 rounded-lg text-[9px] font-bold uppercase tracking-wide transition-all active:scale-95 hover:border-indigo-500/40">
                                                {action.actionId.startsWith('navigate_') ? <ChevronRight className="w-3 h-3" /> : <MousePointerClick className="w-3 h-3" />}
                                                {action.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                                <span className={`text-[9px] font-bold text-slate-600 mt-2 block ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </span>
                            </div>
                        </div>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex justify-start gap-3 animate-fade-in">
                        <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center shrink-0"><Bot className="w-4 h-4 text-white" /></div>
                        <div className="bg-slate-900/80 px-5 py-4 rounded-2xl rounded-tl-none flex gap-1.5 items-center border border-white/5">
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
                        </div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Suspended Input Bar */}
            <div className="p-6 pt-2 bg-gradient-to-t from-[#0f172a] via-[#0f172a] to-transparent">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative group shadow-2xl rounded-2xl">
                    <input 
                        type="text" 
                        value={chatInput} 
                        onChange={(e) => setChatInput(e.target.value)} 
                        placeholder="Type a command or query..." 
                        className="w-full bg-slate-800/80 border border-white/10 text-white text-xs rounded-2xl pl-5 pr-14 py-4 focus:outline-none focus:border-indigo-500 focus:bg-slate-800 transition-all font-medium placeholder:text-slate-500 backdrop-blur-xl" 
                    />
                    <button 
                        type="submit" 
                        disabled={!chatInput.trim() || chatLoading} 
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg active:scale-95"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Lightbulb, Send, Lock, Sparkles, RefreshCw, Flame, ArrowRight, Zap, Crown, TrendingDown, ShoppingCart, Wallet, Terminal, Activity, MousePointerClick, ChevronRight, Check, X, EyeOff, Target, MessageSquare, AlertOctagon, Calendar, ChevronDown, FileText, BarChart3, ScanFace, Command, Radar, Fingerprint } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'Terminal active. I am ready to audit your capital allocation. What is your directive?' 
            : 'Welcome back, Pilot. I\'m ready to help optimize your financial wellness. How can I assist today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState<GoalProposal | null>(null);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "Signal lost. The neural core is currently unreachable. Please retry.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS FOR CLEANER RENDER ---

  const renderDailyReport = () => {
      if (!dailyReport) return null;
      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-start">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-emerald-500/20 rounded-lg"><Zap className="w-4 h-4 text-emerald-400" /></div>
                          <span className="text-xs font-black text-emerald-400 uppercase tracking-widest">Tactical Report</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Daily Ops</h3>
                      <p className="text-slate-400 text-sm font-medium mt-1">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                  </div>
                  <div className="text-right">
                      <div className="relative inline-flex items-center justify-center">
                          <svg className="w-20 h-20 transform -rotate-90">
                              <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-slate-800" />
                              <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={226} strokeDashoffset={226 - (dailyReport.riskScore / 100) * 226} className={dailyReport.riskLevel === 'Critical' ? 'text-rose-500' : dailyReport.riskLevel === 'Warning' ? 'text-amber-400' : 'text-emerald-400'} />
                          </svg>
                          <span className="absolute text-xl font-black text-white">{dailyReport.riskScore.toFixed(0)}</span>
                      </div>
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mt-1">Risk Index</div>
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-5 bg-slate-900/40 rounded-2xl border border-white/5 hover:bg-slate-900/60 transition-colors group">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-slate-400">24h Burn Rate</div>
                      <div className="text-2xl font-mono font-bold text-white">{formatCurrency(dailyReport.totals.expense)}</div>
                  </div>
                  <div className="p-5 bg-slate-900/40 rounded-2xl border border-white/5 hover:bg-slate-900/60 transition-colors group">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 group-hover:text-slate-400">Momentum</div>
                      <div className={`text-2xl font-mono font-bold ${dailyReport.metrics.momentumDelta > 0.1 ? 'text-rose-400' : 'text-emerald-400'}`}>
                          {dailyReport.metrics.momentumDelta > 0 ? '+' : ''}{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%
                      </div>
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Live Signals Detected</h4>
                  {dailyReport.signals.map((sig, idx) => (
                      <div key={idx} className={`flex gap-4 p-4 rounded-xl border backdrop-blur-sm ${sig.type === 'stable' ? 'bg-emerald-500/5 border-emerald-500/10' : 'bg-rose-500/5 border-rose-500/10'}`}>
                          <div className={`mt-1 ${sig.type === 'stable' ? 'text-emerald-400' : 'text-rose-400'}`}>
                              {sig.type === 'stable' ? <CheckCircle className="w-5 h-5" /> : <AlertOctagon className="w-5 h-5" />}
                          </div>
                          <div>
                              <div className="text-sm font-bold text-white mb-0.5">{sig.title}</div>
                              <div className="text-xs text-slate-400 leading-relaxed font-medium">{sig.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              <div className={`p-6 rounded-2xl border flex items-start gap-5 ${dailyReport.action.priority === 'high' ? 'bg-rose-950/30 border-rose-500/30' : 'bg-indigo-950/30 border-indigo-500/30'}`}>
                  <div className={`p-3 rounded-xl shrink-0 ${dailyReport.action.priority === 'high' ? 'bg-rose-500 text-white' : 'bg-indigo-500 text-white'}`}>
                      <Target className="w-5 h-5" />
                  </div>
                  <div>
                      <div className="text-[10px] font-black uppercase tracking-widest mb-1.5 opacity-70 flex items-center gap-2">
                          <span className={`w-2 h-2 rounded-full ${dailyReport.action.priority === 'high' ? 'bg-rose-500' : 'bg-indigo-400'} animate-pulse`}></span>
                          Recommended Action
                      </div>
                      <h4 className="text-base font-bold text-white mb-2">{dailyReport.action.text}</h4>
                      <div className="text-xs font-mono text-slate-300 opacity-80 bg-black/20 p-2 rounded inline-block">Effect: {dailyReport.action.effect}</div>
                  </div>
              </div>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-center">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-amber-500/20 rounded-lg"><Calendar className="w-4 h-4 text-amber-400" /></div>
                          <span className="text-xs font-black text-amber-400 uppercase tracking-widest">Strategic Report</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Monthly Audit</h3>
                      <p className="text-slate-400 text-sm font-medium mt-1">{monthlyReport.month}</p>
                  </div>
                  <div className={`px-4 py-2 bg-white/5 rounded-xl border border-white/10 text-center`}>
                      <div className="text-xs text-slate-500 font-black uppercase tracking-widest">Health Level</div>
                      <span className={`text-lg font-black ${monthlyReport.healthLevel === 'Critical' ? 'text-rose-500' : monthlyReport.healthLevel === 'Fragile' ? 'text-amber-400' : 'text-emerald-400'}`}>{monthlyReport.healthLevel}</span>
                  </div>
              </div>

              <div className="flex justify-center py-6">
                  <div className="relative w-48 h-48 flex items-center justify-center">
                      <div className="absolute inset-0 rounded-full border-[12px] border-slate-800"></div>
                      <div className={`absolute inset-0 rounded-full border-[12px] border-t-transparent border-l-transparent transform -rotate-45 transition-all duration-1000 ${monthlyReport.healthScore >= 80 ? 'border-emerald-500' : monthlyReport.healthScore >= 50 ? 'border-amber-500' : 'border-rose-500'}`} style={{ clipPath: `polygon(0 0, 100% 0, 100% ${monthlyReport.healthScore}%, 0 100%)`}}></div>
                      <div className="text-center z-10">
                          <div className="text-5xl font-black text-white tracking-tighter">{monthlyReport.healthScore.toFixed(0)}</div>
                          <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mt-1">Health Score</div>
                      </div>
                  </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Savings Rate</div>
                      <div className={`text-lg font-mono font-bold ${monthlyReport.metrics.savingsPowerIndex > 0.1 ? 'text-emerald-400' : 'text-rose-400'}`}>{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</div>
                  </div>
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Fixed Load</div>
                      <div className="text-lg font-mono font-bold text-white">{(monthlyReport.metrics.expenseLoadRatio * 100).toFixed(0)}%</div>
                  </div>
                  <div className="p-4 bg-slate-900/40 rounded-xl border border-white/5 text-center hover:bg-slate-900/60 transition-colors">
                      <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Risk Factor</div>
                      <div className={`text-lg font-mono font-bold ${monthlyReport.riskScore > 50 ? 'text-rose-500' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</div>
                  </div>
              </div>

              <div className="bg-gradient-to-br from-indigo-900/20 to-violet-900/20 border border-indigo-500/20 rounded-2xl p-6 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity"><Crown className="w-16 h-16 text-indigo-400" /></div>
                  <h4 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-4 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Mission Objective</h4>
                  <div className="text-lg font-bold text-white mb-6 leading-tight">{monthlyReport.strategicPlan.objective}</div>
                  <div className="space-y-3">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
                          <div key={i} className="flex gap-4 items-start">
                              <span className="flex items-center justify-center w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 text-xs font-bold shrink-0 mt-0.5">{i+1}</span>
                              <span className="text-sm text-slate-300 font-medium">{act}</span>
                          </div>
                      ))}
                  </div>
              </div>

              <div className="space-y-2">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Structural Diagnosis</h4>
                  {monthlyReport.problems.map((prob, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 rounded-xl bg-slate-900/30 border border-white/5">
                          <div className={`w-2 h-2 rounded-full ${prob.severity === 'high' ? 'bg-rose-500 animate-pulse' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                          <span className="text-xs font-medium text-slate-300">{prob.title}</span>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderAiAnalysis = () => {
      if (loading) {
          return (
              <div className="flex flex-col items-center justify-center h-full py-20 space-y-8 animate-fade-in">
                  <div className="relative">
                      <div className="w-16 h-16 bg-indigo-500/10 rounded-full flex items-center justify-center animate-ping absolute"></div>
                      <div className="w-16 h-16 bg-indigo-600 rounded-full flex items-center justify-center relative shadow-[0_0_30px_rgba(99,102,241,0.5)]">
                          <BrainCircuit className="w-8 h-8 text-white animate-pulse" />
                      </div>
                  </div>
                  <div className="text-center space-y-2">
                      <h3 className="text-lg font-bold text-white">Neural Audit Initialized</h3>
                      <p className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em] animate-pulse">Scanning Transaction Vectors...</p>
                  </div>
              </div>
          );
      }
      if (!analysis) return null;

      return (
          <div className="space-y-8 animate-slide-up pb-10">
              <div className="flex justify-between items-start">
                  <div>
                      <div className="flex items-center gap-2 mb-2">
                          <div className="p-1.5 bg-indigo-500/20 rounded-lg"><BrainCircuit className="w-4 h-4 text-indigo-400" /></div>
                          <span className="text-xs font-black text-indigo-400 uppercase tracking-widest">Deep Scan</span>
                      </div>
                      <h3 className="text-3xl font-black text-white uppercase tracking-tight">Neural Audit</h3>
                  </div>
                  <div className={`px-4 py-2 rounded-xl border text-xs font-bold ${analysis.risk_score > 50 ? 'bg-rose-500/10 border-rose-500/20 text-rose-400' : 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'}`}>
                      Risk Score: {Math.round(analysis.risk_score)}/100
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-6 bg-slate-900/40 rounded-2xl border border-white/5">
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Predicted Burn (30d)</div>
                      <div className="text-3xl font-mono font-black text-white">{formatCurrency(analysis.predicted_spend_next_month)}</div>
                  </div>
                  <div className="p-6 bg-slate-900/40 rounded-2xl border border-white/5 flex items-center justify-center">
                      <div className="text-center">
                          <TrendingUp className="w-8 h-8 text-indigo-400 mx-auto mb-2" />
                          <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Trend Analysis</span>
                      </div>
                  </div>
              </div>

              <div className="space-y-4">
                  {analysis.insights.map((insight, idx) => (
                      <div key={idx} className={`p-5 rounded-2xl border flex gap-4 ${insight.type === 'critical' ? 'bg-rose-500/5 border-rose-500/20' : insight.type === 'warning' ? 'bg-amber-500/5 border-amber-500/20' : 'bg-slate-800/30 border-white/5'}`}>
                          <div className="mt-0.5 shrink-0 p-2 bg-black/20 rounded-lg h-fit">
                              {insight.type === 'success' && <CheckCircle className="w-4 h-4 text-emerald-400" />}
                              {insight.type === 'warning' && <AlertTriangle className="w-4 h-4 text-amber-400" />}
                              {insight.type === 'critical' && <ShieldAlert className="w-4 h-4 text-rose-400" />}
                              {insight.type === 'info' && <Info className="w-4 h-4 text-blue-400" />}
                          </div>
                          <div>
                              <div className="text-sm font-bold text-white mb-1">{insight.title}</div>
                              <div className="text-xs text-slate-400 leading-relaxed font-medium">{insight.description}</div>
                          </div>
                      </div>
                  ))}
              </div>

              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-gradient-to-br from-indigo-950/40 to-slate-900 border border-indigo-500/20 p-6 rounded-2xl relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 blur-[50px]"></div>
                      <h3 className="text-xs font-black text-indigo-300 uppercase tracking-widest mb-4 flex items-center gap-2"><Sparkles className="w-3 h-3" /> Strategic Optimization</h3>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-4 relative z-10">
                              <div className="flex justify-between items-start">
                                  <div>
                                      <div className="text-base font-bold text-white">{proposal.title}</div>
                                      <div className="text-xs text-slate-400 mt-1 max-w-sm">{proposal.reason_simple}</div>
                                  </div>
                                  <div className="text-right">
                                      <div className="text-lg font-black text-white font-mono">{formatCurrency(proposal.target_amount)}</div>
                                      <div className="text-[10px] font-bold text-emerald-400 uppercase tracking-widest">Potential Impact</div>
                                  </div>
                              </div>
                              <div className="flex gap-3 pt-2">
                                  <button onClick={() => setShowRejectModal(proposal)} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-400 font-bold text-[10px] uppercase tracking-widest rounded-xl transition-colors border border-white/5">Dismiss</button>
                                  <button onClick={() => handleAcceptProposal(proposal)} className="px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-[10px] uppercase tracking-widest rounded-xl transition-colors shadow-lg shadow-indigo-600/20 flex items-center gap-2">
                                      <Check className="w-3 h-3" /> Execute Protocol
                                  </button>
                              </div>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      );
  };

  return (
    <div className="relative h-[calc(100vh-8rem)]">
      {isLocked && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-md rounded-[3rem] border border-white/10">
            <div className="text-center p-10 max-w-md animate-slide-up bg-[#0f172a] rounded-[2rem] border border-white/10 shadow-2xl">
                <div className="w-20 h-20 rounded-3xl bg-gradient-to-tr from-indigo-600 to-purple-600 flex items-center justify-center mx-auto mb-6 shadow-2xl ring-4 ring-white/10"><Lock className="w-10 h-10 text-white" /></div>
                <h2 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Access Restricted</h2>
                <p className="text-slate-400 mb-8 text-sm font-medium leading-relaxed">Your neural quota of {currentLimit} operations has been exhausted. Upgrade to Elite to unlock unlimited intelligence.</p>
                <button onClick={onUpgradeClick} className="w-full py-4 bg-white text-indigo-950 font-black rounded-xl shadow-xl hover:scale-105 active:scale-95 transition-all text-sm uppercase tracking-widest">Upgrade Terminal</button>
            </div>
        </div>
      )}

      <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 h-full transition-all duration-500 ${isLocked ? 'blur-sm opacity-50 pointer-events-none select-none overflow-hidden' : ''}`}>

        {/* LEFT COLUMN: COMMAND CENTER */}
        <div className="lg:col-span-7 flex flex-col gap-8 overflow-hidden h-full">

            {/* Header Area */}
            <div className="flex items-center justify-between shrink-0">
                <div>
                    <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tighter">
                        <ScanFace className="w-8 h-8 text-indigo-500" />
                        Financial Intelligence
                    </h2>
                    <p className="text-slate-400 text-xs mt-1 font-bold uppercase tracking-widest pl-1">Neural Analysis & Tactical Reporting</p>
                </div>
                <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border ${isUltra ? 'bg-indigo-500/10 border-indigo-500/20 text-indigo-400' : 'bg-slate-800 border-white/10 text-slate-400'}`}>
                    <Fingerprint className="w-3 h-3" />
                    Token Usage: {insightUsage}/{currentLimit}
                </div>
            </div>

            {/* PROTOCOL CHIPS (Command Grid) */}
            <div className="grid grid-cols-3 gap-4 shrink-0">
                <button 
                    onClick={runAnalysis} 
                    disabled={loading}
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'ai' ? 'ring-2 ring-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'ai' ? 'from-indigo-600 to-indigo-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'ai' ? 'bg-indigo-500 text-white shadow-lg' : 'bg-slate-800 text-indigo-400 group-hover:bg-indigo-500 group-hover:text-white'}`}>
                            {loading ? <RefreshCw className="w-6 h-6 animate-spin" /> : <BrainCircuit className="w-6 h-6" />}
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'ai' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Deep Scan</span>
                    </div>
                </button>

                <button 
                    onClick={handleGenerateDaily} 
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'daily' ? 'ring-2 ring-emerald-500 shadow-[0_0_20px_rgba(16,185,129,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'daily' ? 'from-emerald-600 to-emerald-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'daily' ? 'bg-emerald-500 text-white shadow-lg' : 'bg-slate-800 text-emerald-400 group-hover:bg-emerald-500 group-hover:text-white'}`}>
                            <Zap className="w-6 h-6" />
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'daily' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Daily Ops</span>
                    </div>
                </button>

                <button 
                    onClick={handleGenerateMonthly} 
                    className={`relative overflow-hidden p-1 rounded-2xl transition-all active:scale-95 group ${activeView === 'monthly' ? 'ring-2 ring-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.3)]' : 'hover:ring-1 hover:ring-white/20'}`}
                >
                    <div className={`absolute inset-0 bg-gradient-to-br ${activeView === 'monthly' ? 'from-amber-600 to-amber-900' : 'from-slate-800 to-slate-900'} transition-colors`}></div>
                    <div className="relative h-full bg-[#0f172a]/90 backdrop-blur-xl rounded-xl p-4 flex flex-col items-center justify-center gap-3 border border-white/5">
                        <div className={`p-2.5 rounded-xl transition-all ${activeView === 'monthly' ? 'bg-amber-500 text-white shadow-lg' : 'bg-slate-800 text-amber-400 group-hover:bg-amber-500 group-hover:text-white'}`}>
                            <Calendar className="w-6 h-6" />
                        </div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${activeView === 'monthly' ? 'text-white' : 'text-slate-400 group-hover:text-white'}`}>Monthly Strat</span>
                    </div>
                </button>
            </div>

            {/* CONTENT VIEWPORT */}
            <div className="flex-1 bg-slate-900/30 border border-white/5 rounded-[2.5rem] p-8 overflow-y-auto custom-scrollbar relative shadow-inner">
                {activeView === 'idle' && (
                    <div className="h-full flex flex-col items-center justify-center text-center opacity-60">
                        <div className="w-24 h-24 bg-slate-900 rounded-full flex items-center justify-center mb-8 border border-white/5 shadow-2xl relative">
                            <div className="absolute inset-0 border-2 border-indigo-500/20 rounded-full animate-ping"></div>
                            <Radar className="w-10 h-10 text-indigo-500" />
                        </div>
                        <h3 className="text-xl font-bold text-white mb-2 uppercase tracking-tight">Awaiting Directive</h3>
                        <p className="text-slate-500 text-sm max-w-xs font-medium">Initialize a protocol from the command grid above to begin analysis.</p>
                    </div>
                )}

                {activeView === 'ai' && renderAiAnalysis()}
                {activeView === 'daily' && renderDailyReport()}
                {activeView === 'monthly' && renderMonthlyReport()}
            </div>
        </div>

        {/* RIGHT COLUMN: NEURAL LINK (CHAT) */}
        <div className="lg:col-span-5 flex flex-col h-full bg-[#0f172a] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl relative">
            {/* Header */}
            <div className="p-6 border-b border-white/5 bg-slate-900/50 backdrop-blur-md z-10 flex justify-between items-center">
                <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${botMode === 'ruthless' ? 'bg-slate-800' : 'bg-gradient-to-tr from-indigo-500 to-purple-600'}`}>
                        {botMode === 'ruthless' ? <Terminal className="w-5 h-5 text-slate-300" /> : <Bot className="w-5 h-5 text-white" />}
                    </div>
                    <div>
                        <h3 className="font-bold text-white text-sm">Neural Link</h3>
                        <div className="flex items-center gap-1.5 mt-0.5">
                            <div className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'} animate-pulse`}></div>
                            <p className="text-[9px] text-slate-400 font-black uppercase tracking-wider">{botMode === 'ruthless' ? 'Ruthless Logic' : 'Supportive Mode'}</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-900/10 via-transparent to-transparent">
                {chatHistory.map((msg) => (
                    <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                        <div className={`flex gap-3 max-w-[90%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                            <div className={`w-8 h-8 rounded-xl flex items-center justify-center shrink-0 border shadow-sm mt-1 ${msg.role === 'user' ? 'bg-slate-800 border-white/10' : 'bg-indigo-600 border-indigo-500 text-white'}`}>
                                {msg.role === 'user' ? <User className="w-4 h-4 text-slate-400" /> : <Bot className="w-4 h-4" />}
                            </div>
                            <div>
                                <div className={`p-4 text-xs font-medium leading-relaxed shadow-lg rounded-2xl border ${msg.role === 'user' ? 'bg-indigo-900/20 text-indigo-100 rounded-tr-none border-indigo-500/20' : 'bg-slate-900/80 backdrop-blur-md text-slate-200 rounded-tl-none border-white/5'}`}>
                                    {msg.content}
                                </div>
                                {msg.suggestedActions && msg.suggestedActions.length > 0 && (
                                    <div className="flex flex-wrap gap-2 mt-3">
                                        {msg.suggestedActions.map((action, idx) => (
                                            <button key={idx} onClick={() => handleActionClick(action)} className="flex items-center gap-1.5 px-3 py-2 bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/20 text-indigo-300 rounded-lg text-[9px] font-bold uppercase tracking-wide transition-all active:scale-95 hover:border-indigo-500/40">
                                                {action.actionId.startsWith('navigate_') ? <ChevronRight className="w-3 h-3" /> : <MousePointerClick className="w-3 h-3" />}
                                                {action.label}
                                            </button>
                                        ))}
                                    </div>
                                )}
                                <span className={`text-[9px] font-bold text-slate-600 mt-2 block ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </span>
                            </div>
                        </div>
                    </div>
                ))}
                {chatLoading && (
                    <div className="flex justify-start gap-3 animate-fade-in">
                        <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center shrink-0"><Bot className="w-4 h-4 text-white" /></div>
                        <div className="bg-slate-900/80 px-5 py-4 rounded-2xl rounded-tl-none flex gap-1.5 items-center border border-white/5">
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
                        </div>
                    </div>
                )}
                <div ref={chatEndRef} />
            </div>

            {/* Suspended Input Bar */}
            <div className="p-6 pt-2 bg-gradient-to-t from-[#0f172a] via-[#0f172a] to-transparent">
                <form onSubmit={(e) => handleSendMessage(e)} className="relative group shadow-2xl rounded-2xl">
                    <input 
                        type="text" 
                        value={chatInput} 
                        onChange={(e) => setChatInput(e.target.value)} 
                        placeholder="Type a command or query..." 
                        className="w-full bg-slate-800/80 border border-white/10 text-white text-xs rounded-2xl pl-5 pr-14 py-4 focus:outline-none focus:border-indigo-500 focus:bg-slate-800 transition-all font-medium placeholder:text-slate-500 backdrop-blur-xl" 
                    />
                    <button 
                        type="submit" 
                        disabled={!chatInput.trim() || chatLoading} 
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 rounded-xl text-white transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg active:scale-95"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </form>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useRef } from 'react';
import { Transaction, AIAnalysisResponse, ChatMessage, UserPlan, TransactionType, Budget, BotMode, Category, Goal, FinancialSnapshot, SuggestedAction, GoalProposal, DailyReport, MonthlyReport, ReportType } from '../types';
import { analyzeFinancialData, chatWithFinancialCoach } from '../services/geminiService';
import { generateDailyReport, generateMonthlyReport } from '../services/reportEngine';
import { RefreshCcw, CheckCircle, AlertTriangle, ShieldAlert, Info, TrendingUp, Bot, User, BrainCircuit, Send, Lock, Sparkles, RefreshCw, Zap, Crown, Target, Calendar, ChevronRight, Check, Activity, BarChart3, MessageSquare } from 'lucide-react';

interface InsightsProps {
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  initialPrompt?: string | null; 
  onPromptHandled?: () => void; 
  onApplyBudgets?: (budgets: Budget[]) => void; 
  insightUsage: number; 
  onIncrementUsage: () => void; 
  botMode: BotMode;
  onNavigate: (tab: string) => void;
  onAddGoal?: (goal: Goal) => void;
  autoScanTriggered?: boolean;
  activeReport?: ReportType;
  spendingLimit?: number;
}

const Insights: React.FC<InsightsProps> = ({ 
    transactions, 
    goals, 
    budgets, 
    userPlan, 
    onUpgradeClick, 
    formatCurrency, 
    initialPrompt, 
    onPromptHandled, 
    onApplyBudgets, 
    insightUsage, 
    onIncrementUsage, 
    botMode, 
    onNavigate, 
    onAddGoal,
    autoScanTriggered = false,
    activeReport,
    spendingLimit = 1000
}) => {
  const [analysis, setAnalysis] = useState<AIAnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([
    { 
        id: '1', 
        role: 'assistant', 
        content: botMode === 'ruthless' 
            ? 'I am ready to audit your finances. Select a report or ask me a direct question.' 
            : 'Hello! I\'m here to help you optimize your financial wellness. How can I assist you today?', 
        timestamp: new Date(),
        sentiment: 'info'
    }
  ]);
  const [chatLoading, setChatLoading] = useState(false);

  // Dedicated Report State
  const [activeView, setActiveView] = useState<'idle' | 'daily' | 'monthly' | 'ai'>('idle');
  const [dailyReport, setDailyReport] = useState<DailyReport | null>(null);
  const [monthlyReport, setMonthlyReport] = useState<MonthlyReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  const isUltra = userPlan === 'ultra';
  const isPro = userPlan === 'pro';
  const currentLimit = isUltra ? 1500 : isPro ? 50 : 3;
  const isLocked = insightUsage >= currentLimit;

  // Handle activeReport trigger from external nav
  useEffect(() => {
      if (activeReport === 'daily') {
          handleGenerateDaily();
      } else if (activeReport === 'monthly') {
          handleGenerateMonthly();
      }
  }, [activeReport, transactions, spendingLimit]);

  // Initial Prompt Handler
  useEffect(() => {
      if (initialPrompt && onPromptHandled) {
          handleSendMessage(null, initialPrompt);
          onPromptHandled();
      }
  }, [initialPrompt]);

  const handleGenerateDaily = () => {
      const report = generateDailyReport(transactions, spendingLimit || 1000);
      setDailyReport(report);
      setActiveView('daily');
  };

  const handleGenerateMonthly = () => {
      const report = generateMonthlyReport(transactions, spendingLimit || 1000);
      setMonthlyReport(report);
      setActiveView('monthly');
  };

  const runAnalysis = async () => {
    if (isLocked || loading) return;
    setLoading(true);
    setError(null);
    onIncrementUsage();
    setActiveView('ai'); // Switch view immediately to show loading there

    try {
      const result = await analyzeFinancialData(transactions, userPlan);
      if (result) setAnalysis(result);
      else setError("Coach is analyzing other portfolios. Try again.");
    } catch (e) {
      setError("Unable to connect to financial brain.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (autoScanTriggered && !analysis && !loading && !isLocked) {
        runAnalysis();
    }
  }, [autoScanTriggered, analysis, loading, isLocked]);

  const handleAcceptProposal = (proposal: GoalProposal) => {
      if (proposal.type === 'goal' && onAddGoal) {
          onAddGoal({
              id: Date.now().toString(),
              name: proposal.title,
              targetAmount: proposal.target_amount,
              currentAmount: 0,
              deadline: proposal.deadline || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
              icon: 'star',
              color: 'from-emerald-500 to-teal-500'
          });
      } else if (proposal.type === 'budget' && onApplyBudgets) {
          onApplyBudgets([{
              id: `ai_${Date.now()}`,
              category: (proposal.category as Category) || Category.OTHER,
              limit: proposal.target_amount,
              startDate: new Date().toISOString()
          }]);
      }
      if (analysis) setAnalysis({ ...analysis, goal_proposals: analysis.goal_proposals.filter(p => p.id !== proposal.id) });
  };

  const handleSendMessage = async (e: React.FormEvent | null, promptOverride?: string) => {
    if (e) e.preventDefault();
    const content = promptOverride || chatInput;
    if (!content.trim() || isLocked) return;

    onIncrementUsage();
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: content, timestamp: new Date() };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setChatLoading(true);

    const now = new Date();
    const currentMonthTxs = transactions.filter(t => new Date(t.date).getMonth() === now.getMonth());
    const income = currentMonthTxs.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
    const expense = currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

    const catMap: Record<string, number> = {};
    currentMonthTxs.filter(t => t.type === TransactionType.EXPENSE).forEach(t => { catMap[t.category] = (catMap[t.category] || 0) + t.amount; });
    const topCat = Object.entries(catMap).sort((a,b) => b[1] - a[1])[0];

    const snapshot: FinancialSnapshot = {
        currentMonthMetrics: {
            income,
            expense,
            savingsRate: income > 0 ? (income - expense) / income : 0,
            topExpenseCategory: topCat ? topCat[0] : 'None'
        },
        recentTransactions: transactions.slice(0, 10),
        activeGoals: goals,
        budgets: budgets
    };

    try {
        const response = await chatWithFinancialCoach(userMsg.content, chatHistory, snapshot, botMode, userPlan);
        setChatHistory(prev => [...prev, { 
            id: (Date.now() + 1).toString(), 
            role: 'assistant', 
            content: response.message, 
            timestamp: new Date(),
            sentiment: response.sentiment as any,
            suggestedActions: response.suggestedActions
        }]);
    } catch (err) {
        setChatHistory(prev => [...prev, {
            id: (Date.now() + 1).toString(),
            role: 'assistant',
            content: "I'm having trouble connecting to the analysis core right now. Please try again in a moment.",
            timestamp: new Date(),
            sentiment: 'critical'
        }]);
    } finally {
        setChatLoading(false);
    }
  };

  const handleActionClick = (action: SuggestedAction) => {
    if (action.actionId.startsWith('navigate_')) {
        const tab = action.actionId.replace('navigate_', '');
        onNavigate(tab);
    } else if (action.actionId === 'chat_prompt' && action.payload) {
        handleSendMessage(null, action.payload);
    }
  };

  useEffect(() => { chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory, chatLoading]);

  // --- SUB-COMPONENTS ---

  const RiskGauge = ({ score }: { score: number }) => {
      const color = score >= 60 ? '#f43f5e' : score >= 30 ? '#f59e0b' : '#10b981';
      return (
          <div className="relative w-24 h-24 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="48" cy="48" r="40" stroke="#1e293b" strokeWidth="8" fill="transparent" />
                  <circle cx="48" cy="48" r="40" stroke={color} strokeWidth="8" fill="transparent" strokeDasharray={251} strokeDashoffset={251 - (score / 100) * 251} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-2xl font-black text-white">{score}</span>
                  <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500">Risk</span>
              </div>
          </div>
      );
  };

  const HealthGauge = ({ score }: { score: number }) => {
      const color = score >= 80 ? '#10b981' : score >= 50 ? '#f59e0b' : '#f43f5e';
      return (
          <div className="relative w-24 h-24 flex items-center justify-center">
              <svg className="w-full h-full transform -rotate-90">
                  <circle cx="48" cy="48" r="40" stroke="#1e293b" strokeWidth="8" fill="transparent" />
                  <circle cx="48" cy="48" r="40" stroke={color} strokeWidth="8" fill="transparent" strokeDasharray={251} strokeDashoffset={251 - (score / 100) * 251} strokeLinecap="round" />
              </svg>
              <div className="absolute flex flex-col items-center">
                  <span className="text-2xl font-black text-white">{score}</span>
                  <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500">Health</span>
              </div>
          </div>
      );
  };

  const renderDailyReport = () => {
      if (!dailyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up">
              <div className="flex items-center justify-between bg-slate-800/50 p-6 rounded-3xl border border-white/5">
                  <div>
                      <h3 className="text-2xl font-bold text-white mb-1">Daily Brief</h3>
                      <p className="text-slate-400 text-sm">{new Date(dailyReport.date).toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</p>
                  </div>
                  <RiskGauge score={dailyReport.riskScore} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <div className="p-5 bg-slate-900/60 rounded-3xl border border-white/5">
                      <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">24h Spending</p>
                      <p className="text-2xl font-black text-white">{formatCurrency(dailyReport.totals.expense)}</p>
                  </div>
                  <div className="p-5 bg-slate-900/60 rounded-3xl border border-white/5">
                      <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-2">Momentum</p>
                      <p className={`text-2xl font-black ${dailyReport.metrics.momentumDelta > 0.1 ? 'text-rose-400' : 'text-emerald-400'}`}>
                          {dailyReport.metrics.momentumDelta > 0 ? '+' : ''}{(dailyReport.metrics.momentumDelta * 100).toFixed(0)}%
                      </p>
                  </div>
              </div>

              <div className="bg-gradient-to-br from-indigo-600 to-violet-600 p-6 rounded-3xl text-white shadow-lg shadow-indigo-900/20">
                  <div className="flex items-center gap-2 mb-3 opacity-90">
                      <Target className="w-5 h-5" />
                      <span className="text-xs font-bold uppercase tracking-widest">Recommended Action</span>
                  </div>
                  <p className="text-lg font-bold leading-tight">{dailyReport.action.text}</p>
                  <div className="mt-4 pt-4 border-t border-white/20 flex items-center gap-2 text-xs font-medium opacity-80">
                      <CheckCircle className="w-4 h-4" />
                      Effect: {dailyReport.action.effect}
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider px-2">Signals</h4>
                  {dailyReport.signals.map((sig, idx) => (
                      <div key={idx} className="flex gap-4 p-4 bg-slate-900/40 rounded-2xl border border-white/5">
                          {sig.type === 'stable' ? <CheckCircle className="w-5 h-5 text-emerald-500 shrink-0" /> : <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0" />}
                          <div>
                              <p className="text-sm font-bold text-white">{sig.title}</p>
                              <p className="text-xs text-slate-400 mt-1">{sig.description}</p>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderMonthlyReport = () => {
      if (!monthlyReport) return null;
      return (
          <div className="space-y-6 animate-slide-up">
              <div className="flex items-center justify-between bg-slate-800/50 p-6 rounded-3xl border border-white/5">
                  <div>
                      <h3 className="text-2xl font-bold text-white mb-1">Monthly Audit</h3>
                      <p className="text-slate-400 text-sm">{monthlyReport.month}</p>
                  </div>
                  <HealthGauge score={monthlyReport.healthScore} />
              </div>

              <div className="grid grid-cols-3 gap-3">
                  <div className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wider mb-1">Savings Rate</p>
                      <p className={`text-lg font-black ${monthlyReport.metrics.savingsPowerIndex > 0.1 ? 'text-emerald-400' : 'text-rose-400'}`}>{(monthlyReport.metrics.savingsPowerIndex * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wider mb-1">Fixed Load</p>
                      <p className="text-lg font-black text-white">{(monthlyReport.metrics.expenseLoadRatio * 100).toFixed(0)}%</p>
                  </div>
                  <div className="p-4 bg-slate-900/60 rounded-2xl border border-white/5 text-center">
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wider mb-1">Risk Factor</p>
                      <p className={`text-lg font-black ${monthlyReport.riskScore > 50 ? 'text-rose-400' : 'text-emerald-400'}`}>{monthlyReport.riskScore.toFixed(0)}</p>
                  </div>
              </div>

              <div className="bg-slate-900/80 p-6 rounded-3xl border border-indigo-500/20 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-6 opacity-5"><Crown className="w-24 h-24" /></div>
                  <h4 className="text-indigo-400 text-xs font-bold uppercase tracking-widest mb-3 flex items-center gap-2"><Sparkles className="w-4 h-4" /> Strategic Objective</h4>
                  <p className="text-xl font-bold text-white mb-4">{monthlyReport.strategicPlan.objective}</p>
                  <ul className="space-y-2">
                      {monthlyReport.strategicPlan.actions.map((act, i) => (
                          <li key={i} className="flex items-start gap-3 text-sm text-slate-300">
                              <span className="w-5 h-5 rounded-full bg-indigo-500/20 text-indigo-400 flex items-center justify-center text-xs font-bold shrink-0 mt-0.5">{i+1}</span>
                              {act}
                          </li>
                      ))}
                  </ul>
              </div>

              <div className="space-y-3">
                  <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider px-2">Key Issues</h4>
                  {monthlyReport.problems.map((prob, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-4 bg-slate-900/40 rounded-2xl border border-white/5">
                          <div className={`w-2 h-2 rounded-full ${prob.severity === 'high' ? 'bg-rose-500' : prob.severity === 'medium' ? 'bg-amber-500' : 'bg-blue-500'}`}></div>
                          <p className="text-sm font-medium text-slate-300">{prob.title}</p>
                      </div>
                  ))}
              </div>
          </div>
      );
  };

  const renderAiAnalysis = () => {
      if (loading) {
          return (
              <div className="h-full flex flex-col items-center justify-center p-10 text-center animate-fade-in">
                  <div className="relative mb-6">
                      <div className="w-16 h-16 bg-indigo-600 rounded-2xl animate-spin"></div>
                      <div className="absolute inset-0 flex items-center justify-center"><BrainCircuit className="w-8 h-8 text-white" /></div>
                  </div>
                  <h3 className="text-lg font-bold text-white mb-2">Analyzing Financial Matrix...</h3>
                  <p className="text-slate-500 text-xs uppercase tracking-widest">Processing Transaction Vectors</p>
              </div>
          );
      }
      if (!analysis) return null;

      return (
          <div className="space-y-6 animate-slide-up">
              <div className="flex items-center justify-between bg-slate-800/50 p-6 rounded-3xl border border-white/5">
                  <div>
                      <h3 className="text-2xl font-bold text-white mb-1">Deep Scan</h3>
                      <p className="text-slate-400 text-sm">AI-Powered Audit</p>
                  </div>
                  <RiskGauge score={analysis.riskScore || analysis.risk_score} />
              </div>

              <div className="p-6 bg-slate-900/60 rounded-3xl border border-white/5 flex items-center justify-between">
                  <div>
                      <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">Predicted Spend (30d)</p>
                      <p className="text-3xl font-black text-white">{formatCurrency(analysis.predicted_spend_next_month)}</p>
                  </div>
                  <div className="p-4 bg-slate-800 rounded-2xl">
                      <TrendingUp className="w-6 h-6 text-indigo-400" />
                  </div>
              </div>

              <div className="space-y-3">
                  <h4 className="text-slate-500 text-xs font-bold uppercase tracking-wider px-2">Insights</h4>
                  {analysis.insights.map((insight, idx) => (
                      <div key={idx} className="p-5 bg-slate-900/40 rounded-2xl border border-white/5">
                          <div className="flex items-center gap-2 mb-2">
                              {insight.type === 'success' && <CheckCircle className="w-4 h-4 text-emerald-400" />}
                              {insight.type === 'warning' && <AlertTriangle className="w-4 h-4 text-amber-400" />}
                              {insight.type === 'critical' && <ShieldAlert className="w-4 h-4 text-rose-400" />}
                              {insight.type === 'info' && <Info className="w-4 h-4 text-blue-400" />}
                              <span className="text-sm font-bold text-white">{insight.title}</span>
                          </div>
                          <p className="text-xs text-slate-400 leading-relaxed">{insight.description}</p>
                      </div>
                  ))}
              </div>

              {analysis.goal_proposals && analysis.goal_proposals.length > 0 && (
                  <div className="bg-slate-900/80 p-6 rounded-3xl border border-emerald-500/20">
                      <h4 className="text-emerald-400 text-xs font-bold uppercase tracking-widest mb-4 flex items-center gap-2"><Sparkles className="w-4 h-4" /> Opportunity Detected</h4>
                      {analysis.goal_proposals.map((proposal) => (
                          <div key={proposal.id} className="space-y-4">
                              <div className="flex justify-between items-start">
                                  <div>
                                      <p className="text-lg font-bold text-white">{proposal.title}</p>
                                      <p className="text-xs text-slate-400 mt-1 max-w-xs">{proposal.reason_simple}</p>
                                  </div>
                                  <div className="text-right">
                                      <p className="text-xl font-bold text-emerald-400">{formatCurrency(proposal.target_amount)}</p>
                                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Target</p>
                                  </div>
                              </div>
                              <button onClick={() => handleAcceptProposal(proposal)} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 text-white font-bold rounded-xl text-xs uppercase tracking-widest shadow-lg shadow-emerald-900/20 transition-all flex items-center justify-center gap-2">
                                  <Check className="w-4 h-4" /> Accept Recommendation
                              </button>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      );
  };

  return (
    <div className="h-[calc(100vh-8rem)]">
        {isLocked && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
                <div className="bg-slate-900 border border-white/10 p-8 rounded-3xl max-w-sm text-center shadow-2xl">
                    <div className="w-16 h-16 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg">
                        <Lock className="w-8 h-8 text-white" />
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Usage Limit Reached</h3>
                    <p className="text-slate-400 text-sm mb-6">You've used all {currentLimit} free AI analyses for this cycle. Upgrade to Elite for unlimited access.</p>
                    <button onClick={onUpgradeClick} className="w-full py-3 bg-white text-slate-900 font-bold rounded-xl hover:scale-105 transition-all">Upgrade Now</button>
                </div>
            </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-full">
            {/* Left Column: Tools & Reports */}
            <div className="lg:col-span-7 flex flex-col gap-6 h-full overflow-hidden">
                <div className="shrink-0 flex items-center justify-between">
                    <div>
                        <h2 className="text-2xl font-black text-white tracking-tight flex items-center gap-2">
                            <Bot className="w-6 h-6 text-indigo-500" /> Financial Coach
                        </h2>
                        <p className="text-slate-400 text-xs font-medium mt-1">AI-Powered Insights & Analysis</p>
                    </div>
                    <div className="px-3 py-1 bg-slate-800 rounded-full border border-white/5 text-[10px] font-bold text-slate-400">
                        {insightUsage} / {currentLimit} Credits
                    </div>
                </div>

                <div className="shrink-0 grid grid-cols-3 gap-3">
                    <button 
                        onClick={handleGenerateDaily}
                        className={`p-4 rounded-2xl border transition-all text-left group hover:scale-[1.02] ${activeView === 'daily' ? 'bg-indigo-600 text-white border-indigo-500 shadow-lg shadow-indigo-900/20' : 'bg-slate-800/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                    >
                        <Zap className={`w-6 h-6 mb-3 ${activeView === 'daily' ? 'text-white' : 'text-indigo-400'}`} />
                        <div className="font-bold text-sm">Daily Brief</div>
                        <div className="text-[10px] opacity-60">Snapshot</div>
                    </button>
                    <button 
                        onClick={handleGenerateMonthly}
                        className={`p-4 rounded-2xl border transition-all text-left group hover:scale-[1.02] ${activeView === 'monthly' ? 'bg-indigo-600 text-white border-indigo-500 shadow-lg shadow-indigo-900/20' : 'bg-slate-800/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                    >
                        <Calendar className={`w-6 h-6 mb-3 ${activeView === 'monthly' ? 'text-white' : 'text-amber-400'}`} />
                        <div className="font-bold text-sm">Monthly Review</div>
                        <div className="text-[10px] opacity-60">Audit</div>
                    </button>
                    <button 
                        onClick={runAnalysis}
                        disabled={loading}
                        className={`p-4 rounded-2xl border transition-all text-left group hover:scale-[1.02] ${activeView === 'ai' ? 'bg-indigo-600 text-white border-indigo-500 shadow-lg shadow-indigo-900/20' : 'bg-slate-800/50 text-slate-400 border-white/5 hover:bg-slate-800 hover:text-white'}`}
                    >
                        {loading ? <RefreshCw className="w-6 h-6 mb-3 animate-spin" /> : <BrainCircuit className={`w-6 h-6 mb-3 ${activeView === 'ai' ? 'text-white' : 'text-emerald-400'}`} />}
                        <div className="font-bold text-sm">Deep Scan</div>
                        <div className="text-[10px] opacity-60">AI Powered</div>
                    </button>
                </div>

                <div className="flex-1 bg-slate-900/30 rounded-[2.5rem] border border-white/5 p-6 overflow-y-auto custom-scrollbar">
                    {activeView === 'idle' && (
                        <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
                            <Activity className="w-16 h-16 text-slate-600 mb-4" />
                            <h3 className="text-lg font-bold text-white mb-2">Ready to Analyze</h3>
                            <p className="text-sm text-slate-400 max-w-xs">Select a report type above to generate insights.</p>
                        </div>
                    )}
                    {activeView === 'daily' && renderDailyReport()}
                    {activeView === 'monthly' && renderMonthlyReport()}
                    {activeView === 'ai' && renderAiAnalysis()}
                </div>
            </div>

            {/* Right Column: Chat */}
            <div className="lg:col-span-5 bg-slate-900/80 border border-white/10 rounded-[2.5rem] flex flex-col overflow-hidden shadow-2xl relative">
                <div className="p-5 border-b border-white/5 bg-slate-950/50 backdrop-blur-md flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg">
                            <MessageSquare className="w-5 h-5 text-white" />
                        </div>
                        <div>
                            <h3 className="font-bold text-white text-sm">Assistant</h3>
                            <div className="flex items-center gap-1.5">
                                <span className={`w-1.5 h-1.5 rounded-full ${botMode === 'ruthless' ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{botMode === 'ruthless' ? 'Ruthless' : 'Supportive'} Mode</span>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-900/10 via-transparent to-transparent">
                    {chatHistory.map((msg) => (
                        <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-slide-up`}>
                            <div className={`max-w-[85%] p-4 rounded-2xl text-sm font-medium leading-relaxed shadow-md ${msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-slate-800 text-slate-200 rounded-tl-none border border-white/5'}`}>
                                {msg.content}
                            </div>
                            {msg.suggestedActions && (
                                <div className="flex flex-wrap gap-2 mt-2 justify-start">
                                    {msg.suggestedActions.map((action, idx) => (
                                        <button key={idx} onClick={() => handleActionClick(action)} className="px-3 py-1.5 bg-indigo-500/10 hover:bg-indigo-500/20 text-indigo-300 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-indigo-500/20 transition-all">
                                            {action.label}
                                        </button>
                                    ))}
                                </div>
                            )}
                            <span className="text-[9px] text-slate-600 font-bold mt-1 px-1">{msg.timestamp.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
                        </div>
                    ))}
                    {chatLoading && (
                        <div className="flex items-center gap-2 p-4 bg-slate-800 rounded-2xl rounded-tl-none w-16">
                            <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce"></div>
                            <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-100"></div>
                            <div className="w-1.5 h-1.5 bg-slate-500 rounded-full animate-bounce delay-200"></div>
                        </div>
                    )}
                    <div ref={chatEndRef} />
                </div>

                <div className="p-4 bg-slate-950 border-t border-white/5">
                    <form onSubmit={handleSendMessage} className="relative">
                        <input 
                            type="text" 
                            value={chatInput} 
                            onChange={(e) => setChatInput(e.target.value)} 
                            placeholder="Ask me anything..." 
                            className="w-full bg-slate-900 border border-white/10 rounded-xl pl-4 pr-12 py-3.5 text-sm text-white focus:outline-none focus:border-indigo-500 transition-all placeholder:text-slate-600"
                        />
                        <button 
                            type="submit" 
                            disabled={!chatInput.trim() || chatLoading} 
                            className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all disabled:opacity-50 shadow-lg active:scale-95"
                        >
                            <Send className="w-4 h-4" />
                        </button>
                    </form>
                </div>
            </div>
        </div>
    </div>
  );
};

export default Insights;

import React, { useState, useEffect, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus, ReportType } from '../types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from '../constants';
import { evaluateSpending } from '../services/ruleEngine';
import Dashboard from './Dashboard';
import Transactions from './Transactions';
import Accounts from './Accounts';
import Insights from './Insights';
import Goals from './Goals';
import Plans from './Plans';
import Settings from './Settings';
import SmartMoney from './SmartMoney';
import Investment from './Investment';
import UpcomingFeatures from './UpcomingFeatures';
import LandingPage from './LandingPage';
import OnboardingModal from './OnboardingModal';
import ToastContainer from './Toast';
import FloatingAssistant from './FloatingAssistant';
import MobileNav from './MobileNav';
import { Sparkles, LogOut, Zap, Shield, EyeOff, LayoutDashboard, CreditCard, Landmark, Target, Settings as SettingsIcon, Lock } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [smartMoneyTab, setSmartMoneyTab] = useState('burn_vector');
  const [activeReport, setActiveReport] = useState<ReportType>(null);
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  // Derived State
  const currentPeriodSpend = useMemo(() => {
      const now = new Date();
      return transactions
        .filter(t => {
            const d = new Date(t.date);
            if (t.type !== TransactionType.EXPENSE) return false;

            if (spendingPeriod === 'monthly') {
                return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
            } else {
                // Weekly logic: simple 7 day lookback for now
                const oneWeekAgo = new Date();
                oneWeekAgo.setDate(now.getDate() - 7);
                return d >= oneWeekAgo && d <= now;
            }
        })
        .reduce((acc, t) => acc + t.amount, 0);
  }, [transactions, spendingPeriod]);

  const spendingStatus = useMemo(() => evaluateSpending(currentPeriodSpend, spendingLimit), [currentPeriodSpend, spendingLimit]);

  // Enhanced Format Currency with Privacy Logic
  const formatCurrency = (amount: number) => {
    if (isPrivacyMode) return '••••••';
    return new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', {
      style: 'currency',
      currency: currency
    }).format(amount);
  };

  const addToast = (message: string, type: ToastMessage['type'] = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), type, message }]);
  };

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleNavigate = (tab: string, params?: any) => {
    setActiveTab(tab);
    if (tab === 'smart_money' && params?.tab) {
        setSmartMoneyTab(params.tab);
    }
    if (tab === 'insights' && params?.reportType) {
        setActiveReport(params.reportType);
    }
  };

  const handleAddTransaction = (newTx: Transaction) => {
      setTransactions(prev => [newTx, ...prev]);

      const accIndex = accounts.findIndex(a => a.id === newTx.accountId);
      if (accIndex >= 0) {
          const updatedAccounts = [...accounts];
          if (newTx.type === TransactionType.INCOME) {
              updatedAccounts[accIndex].balance += newTx.amount;
          } else {
              updatedAccounts[accIndex].balance -= newTx.amount;
          }
          setAccounts(updatedAccounts);
      }
      addToast('Transaction recorded successfully', 'success');
  };

  const handleUpdateProfile = (name: string, email: string, avatar: string, zoom: number, pos: {x:number, y:number}, border: string) => {
      setUserName(name);
      setUserEmail(email);
      setUserAvatar(avatar);
      setUserAvatarZoom(zoom);
      setUserAvatarPos(pos);
      setUserBorder(border);
      localStorage.setItem('nova_user_name', name);
      localStorage.setItem('nova_user_email', email);
      localStorage.setItem('nova_user_avatar', avatar);
      localStorage.setItem('nova_user_avatar_zoom', zoom.toString());
      localStorage.setItem('nova_user_avatar_pos', JSON.stringify(pos));
      localStorage.setItem('nova_user_border', border);
  };

  const handleIncrementUsage = (type: 'insight' | 'scan' | 'negotiation', amount = 1) => {
      const key = `nova_${type}_usage`;
      const now = new Date();
      const current = type === 'insight' ? insightUsage : type === 'scan' ? scanUsage : negotiationUsage;
      const newVal = current + amount;

      const record = { count: newVal, month: now.getMonth(), year: now.getFullYear() };
      localStorage.setItem(key, JSON.stringify(record));

      if (type === 'insight') setInsightUsage(newVal);
      else if (type === 'scan') setScanUsage(newVal);
      else setNegotiationUsage(newVal);
  };

  if (!isLoggedIn) {
      return (
          <>
            <LandingPage onLoginSuccess={(name) => {
                setUserName(name);
                setIsLoggedIn(true);
                localStorage.setItem('nova_auth_token', 'mock_token');
                localStorage.setItem('nova_user_name', name);
                addToast(`Welcome back, ${name}. Vault unlocked.`, 'success');
            }} />
            <ToastContainer toasts={toasts} onRemove={removeToast} />
          </>
      );
  }

  return (
    <div className="flex h-screen bg-[#020617] text-slate-200 font-sans selection:bg-indigo-500/30 overflow-hidden" 
         style={{ backgroundImage: userBackground ? `url(${userBackground})` : 'none', backgroundSize: 'cover', backgroundPosition: 'center' }}>

        {/* Dark Overlay for Readability if Background is set */}
        {userBackground && <div className="absolute inset-0 bg-[#020617]/80 backdrop-blur-[2px] z-0"></div>}

        {/* Sidebar */}
        <div className="hidden md:flex w-64 flex-col bg-[#0f172a]/95 border-r border-white/5 relative z-10 backdrop-blur-xl">
            <div className="p-6 border-b border-white/5 flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-indigo-600 flex items-center justify-center shadow-lg shadow-indigo-600/20">
                    <Sparkles className="w-5 h-5 text-white" />
                </div>
                <span className="font-bold text-lg tracking-tight text-white">Nova Finance</span>
            </div>

            <nav className="flex-1 overflow-y-auto p-4 space-y-1 custom-scrollbar">
                {NAV_ITEMS.map((item) => (
                    <button
                        key={item.id}
                        onClick={() => handleNavigate(item.id)}
                        className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group ${activeTab === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-900/20' : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}`}
                    >
                        <item.icon className={`w-5 h-5 ${activeTab === item.id ? 'text-white' : 'text-slate-500 group-hover:text-slate-300'}`} />
                        <span className="text-sm font-medium">{item.label}</span>
                    </button>
                ))}
            </nav>

            <div className="p-4 border-t border-white/5 bg-slate-900/50">
                <div 
                    onClick={() => handleNavigate('settings')} 
                    className="flex items-center gap-3 mb-4 cursor-pointer hover:bg-white/5 p-2 rounded-xl transition-colors group"
                >
                    {userAvatar ? (
                        <img src={userAvatar} alt="Profile" className="w-10 h-10 rounded-full object-cover border-2 border-slate-700 group-hover:border-indigo-500 transition-colors" />
                    ) : (
                        <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-slate-400 border border-slate-700 group-hover:border-indigo-500 transition-colors">
                            {userName.charAt(0).toUpperCase()}
                        </div>
                    )}
                    <div className="flex-1 min-w-0">
                        <div className="text-sm font-bold text-white truncate group-hover:text-indigo-400 transition-colors">{userName}</div>
                        <div className="text-xs text-slate-500 truncate">{userPlan.toUpperCase()} Plan</div>
                    </div>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsLogoutModalOpen(true); }} 
                        className="p-2 text-slate-500 hover:text-rose-400 transition-colors rounded-lg hover:bg-rose-500/10"
                    >
                        <LogOut className="w-4 h-4" />
                    </button>
                </div>
                <div 
                    onClick={() => {
                        if (userPlan !== 'ultra') {
                            addToast("Privacy Mode is restricted to Elite Terminal.", "error");
                            handleNavigate('plans');
                            return;
                        }
                        setIsPrivacyMode(!isPrivacyMode);
                    }}
                    className={`flex items-center justify-between text-[10px] text-slate-500 font-bold uppercase tracking-wider px-2 cursor-pointer group ${userPlan !== 'ultra' ? 'opacity-60' : ''}`}
                >
                    <span className="group-hover:text-slate-300 transition-colors flex items-center gap-1.5">
                        Privacy Mode
                        {userPlan !== 'ultra' && <Lock className="w-3 h-3 text-indigo-400" />}
                    </span>
                    <div 
                        className={`w-10 h-5 rounded-full relative transition-colors duration-300 ${isPrivacyMode ? 'bg-emerald-500' : 'bg-slate-700'}`}
                    >
                        <div className={`absolute top-1 left-1 w-3 h-3 rounded-full bg-white transition-transform duration-300 ${isPrivacyMode ? 'translate-x-5' : 'translate-x-0'}`}></div>
                    </div>
                </div>
            </div>
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col relative z-10 overflow-hidden">
            {/* Mobile Header */}
            <div className="md:hidden h-16 bg-[#0f172a]/90 backdrop-blur-xl border-b border-white/5 flex items-center justify-between px-4 z-20">
                <div className="flex items-center gap-2">
                    <Sparkles className="w-6 h-6 text-indigo-500" />
                    <span className="font-bold text-white">Nova</span>
                </div>
                <div className="flex items-center gap-3">
                    <button onClick={() => setAutoScanTrigger(true)} className="p-2 bg-slate-800 rounded-full text-indigo-400"><Zap className="w-4 h-4" /></button>
                </div>
            </div>

            <main className="flex-1 overflow-y-auto overflow-x-hidden p-4 md:p-8 custom-scrollbar">
                <div className="max-w-7xl mx-auto h-full">
                    {activeTab === 'dashboard' && (
                        <Dashboard 
                            accounts={accounts} 
                            transactions={transactions} 
                            goals={goals} 
                            budgets={budgets} 
                            onNavigate={handleNavigate}
                            onAddTransaction={() => handleNavigate('transactions')}
                            onAddGoal={() => handleNavigate('goals')}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onAskCoach={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                            insightUsage={insightUsage}
                            spendingStatus={spendingStatus}
                            currentPeriodSpend={currentPeriodSpend}
                            spendingLimit={spendingLimit}
                            spendingPeriod={spendingPeriod}
                            userName={userName}
                            isPrivacyMode={isPrivacyMode}
                        />
                    )}
                    {activeTab === 'transactions' && (
                        <Transactions 
                            transactions={transactions}
                            accounts={accounts}
                            onDelete={(id) => {
                                const tx = transactions.find(t => t.id === id);
                                if (tx) {
                                    setTransactions(prev => prev.filter(t => t.id !== id));
                                    // Revert balance
                                    const accIndex = accounts.findIndex(a => a.id === tx.accountId);
                                    if (accIndex >= 0) {
                                        const updated = [...accounts];
                                        if (tx.type === TransactionType.INCOME) updated[accIndex].balance -= tx.amount;
                                        else updated[accIndex].balance += tx.amount;
                                        setAccounts(updated);
                                    }
                                }
                            }}
                            onAdd={handleAddTransaction}
                            formatCurrency={formatCurrency}
                            onNavigateToAccounts={() => handleNavigate('accounts')}
                            userPlan={userPlan}
                            scanUsage={scanUsage}
                            onIncrementScan={() => handleIncrementUsage('scan')}
                            currency={currency}
                        />
                    )}
                    {activeTab === 'accounts' && (
                        <Accounts 
                            accounts={accounts}
                            budgets={budgets}
                            transactions={transactions}
                            userPlan={userPlan}
                            onAdd={(acc) => setAccounts(prev => [...prev, acc])}
                            onUpdate={(acc) => setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a))}
                            onDelete={(id) => setAccounts(prev => prev.filter(a => a.id !== id))}
                            formatCurrency={formatCurrency}
                            userName={userName}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            onNavigate={handleNavigate}
                        />
                    )}
                    {activeTab === 'insights' && (
                        <Insights 
                            transactions={transactions}
                            goals={goals}
                            budgets={budgets}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            formatCurrency={formatCurrency}
                            initialPrompt={pendingChatQuery}
                            onPromptHandled={() => setPendingChatQuery(null)}
                            onApplyBudgets={(newBudgets) => setBudgets(prev => [...prev, ...newBudgets])}
                            insightUsage={insightUsage}
                            onIncrementUsage={() => handleIncrementUsage('insight')}
                            botMode={botMode}
                            onNavigate={handleNavigate}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            autoScanTriggered={autoScanTrigger}
                            activeReport={activeReport}
                            spendingLimit={spendingLimit}
                        />
                    )}
                    {activeTab === 'smart_money' && (
                        <SmartMoney 
                            initialTab={smartMoneyTab}
                            transactions={transactions}
                            accounts={accounts}
                            goals={goals}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                            onUpgradeClick={() => handleNavigate('plans')}
                            insightUsage={insightUsage}
                            onIncrementUsage={(n) => handleIncrementUsage('insight', n)}
                            negotiationUsage={negotiationUsage}
                            onIncrementNegotiationUsage={() => handleIncrementUsage('negotiation')}
                        />
                    )}
                    {activeTab === 'goals' && (
                        <Goals 
                            goals={goals}
                            budgets={budgets}
                            transactions={transactions}
                            onAddGoal={(g) => setGoals(prev => [...prev, g])}
                            onUpdateGoal={(g) => setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal))}
                            onAddBudget={(b) => setBudgets(prev => [...prev, b])}
                            onDeleteBudget={(id) => setBudgets(prev => prev.filter(b => b.id !== id))}
                            formatCurrency={formatCurrency}
                        />
                    )}
                    {activeTab === 'plans' && (
                        <Plans 
                            currentPlan={userPlan}
                            onUpgrade={(plan) => setUserPlan(plan)}
                            onDowngrade={() => setUserPlan('free')}
                            onNavigateDashboard={() => handleNavigate('dashboard')}
                        />
                    )}
                    {activeTab === 'settings' && (
                        <Settings 
                            userName={userName}
                            userEmail={userEmail}
                            userAvatar={userAvatar}
                            userAvatarZoom={userAvatarZoom}
                            userAvatarPos={userAvatarPos}
                            userBorder={userBorder}
                            userBackground={userBackground}
                            onUpdateBackground={(bg) => setUserBackground(bg)}
                            userPlan={userPlan}
                            onUpdateProfile={handleUpdateProfile}
                            addToast={addToast}
                            onExportData={() => {
                                const data = { accounts, transactions, budgets, goals, userPlan };
                                const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
                                const url = URL.createObjectURL(blob);
                                const a = document.createElement('a');
                                a.href = url;
                                a.download = `nova_backup_${new Date().toISOString()}.json`;
                                a.click();
                            }}
                            onImportData={(file) => {
                                const reader = new FileReader();
                                reader.onload = (e) => {
                                    try {
                                        const data = JSON.parse(e.target?.result as string);
                                        if (data.accounts) setAccounts(data.accounts);
                                        if (data.transactions) setTransactions(data.transactions);
                                        if (data.budgets) setBudgets(data.budgets);
                                        if (data.goals) setGoals(data.goals);
                                        addToast('Data restored successfully', 'success');
                                    } catch (err) {
                                        addToast('Invalid backup file', 'error');
                                    }
                                };
                                reader.readAsText(file);
                            }}
                            onClearData={() => {
                                setAccounts(ACCOUNTS);
                                setTransactions(INITIAL_TRANSACTIONS);
                                setBudgets(INITIAL_BUDGETS);
                                setGoals(INITIAL_GOALS);
                                addToast('System reset complete', 'info');
                            }}
                            language={language}
                            onUpdateLanguage={setLanguage}
                            currency={currency}
                            onUpdateCurrency={setCurrency}
                            botMode={botMode}
                            onUpdateBotMode={setBotMode}
                            onDowngrade={() => setUserPlan('free')}
                            spendingLimit={spendingLimit}
                            onUpdateSpendingLimit={setSpendingLimit}
                            spendingPeriod={spendingPeriod}
                            onUpdateSpendingPeriod={setSpendingPeriod}
                        />
                    )}
                    {activeTab === 'investment' && (
                        <Investment 
                            accounts={accounts}
                            formatCurrency={formatCurrency}
                            userPlan={userPlan}
                        />
                    )}
                    {activeTab === 'upcoming' && <UpcomingFeatures />}
                </div>
            </main>

            {isLoggedIn && !onboardingComplete && (
                <OnboardingModal onComplete={(name, lang, period, limit) => {
                    setUserName(name);
                    setLanguage(lang);
                    setSpendingPeriod(period);
                    setSpendingLimit(limit);
                    setOnboardingComplete(true);
                    localStorage.setItem('nova_onboarding_complete', 'true');
                    addToast("Core initialized. Welcome to Nova.", "success");
                }} />
            )}

            <MobileNav 
                activeTab={activeTab} 
                onNavigate={handleNavigate} 
                onAddTransaction={() => handleNavigate('transactions')} 
            />

            <ToastContainer toasts={toasts} onRemove={removeToast} />

            <FloatingAssistant 
                transactions={transactions} 
                budgets={budgets} 
                userPlan={userPlan} 
                botMode={botMode}
                onOpenChat={(q) => { setPendingChatQuery(q); handleNavigate('insights'); }}
                isVisible={activeTab !== 'insights'}
                insightUsage={insightUsage}
            />

            {isLogoutModalOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
                    <div className="bg-slate-900 border border-white/10 rounded-2xl p-6 w-full max-w-sm shadow-2xl animate-slide-up">
                        <h3 className="text-lg font-bold text-white mb-2">Terminate Session?</h3>
                        <p className="text-slate-400 text-sm mb-6">Your local data will persist, but you will need to re-authenticate to access the vault.</p>
                        <div className="flex justify-end gap-3">
                            <button onClick={() => setIsLogoutModalOpen(false)} className="px-4 py-2 text-slate-300 hover:text-white font-medium">Cancel</button>
                            <button 
                                onClick={() => {
                                    setIsLoggedIn(false);
                                    setIsLogoutModalOpen(false);
                                    localStorage.removeItem('nova_auth_token');
                                }} 
                                className="px-4 py-2 bg-rose-600 hover:bg-rose-500 text-white rounded-lg font-bold shadow-lg"
                            >
                                Logout
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { ComposedChart, Line, Area, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Plus, Rocket, BarChart3, Clock } from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddAccount?: () => void;
  onAddTransaction?: () => void;
  onAddGoal?: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan?: UserPlan;
  onAskCoach?: (message: string) => void;
  isPinMode?: boolean;
  pinnedIds?: string[];
  onTogglePin?: (id: string) => void;
  trackEvent?: (id: string) => void;
  insightUsage?: number;
  spendingStatus?: SpendingStatus;
  currentPeriodSpend?: number;
  spendingLimit?: number;
  spendingPeriod?: SpendingPeriod;
  userName?: string;
  isPrivacyMode?: boolean;
}

const COLORS = ['#3b82f6', '#f97316', '#10b981', '#8b5cf6', '#06b6d4', '#ec4899', '#64748b'];

const Dashboard: React.FC<DashboardProps> = ({ 
    accounts, 
    transactions, 
    goals, 
    budgets,
    onNavigate, 
    onAddAccount, 
    onAddTransaction, 
    onAddGoal, 
    formatCurrency, 
    userPlan, 
    onAskCoach, 
    insightUsage = 0,
    spendingStatus,
    currentPeriodSpend = 0,
    spendingLimit = 1000,
    spendingPeriod = 'monthly',
    userName = 'Pilot',
    isPrivacyMode = false
}) => {
  const [spendingComparison, setSpendingComparison] = useState<'year' | 'month'>('year');
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [showScanConfirm, setShowScanConfirm] = useState(false);

  // Close menus on click outside
  useEffect(() => {
      const handleClickOutside = () => setActiveMenu(null);
      document.addEventListener('click', handleClickOutside);
      return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const toggleMenu = (e: React.MouseEvent, menuId: string) => {
      e.stopPropagation();
      setActiveMenu(activeMenu === menuId ? null : menuId);
  };

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const dayName = today.toLocaleDateString('en-US', { weekday: 'long' });

  // Capture timestamp on mount/render for "Last Updated"
  const lastUpdated = useMemo(() => new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), []);

  const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const creditCardDebt = useMemo(() => {
      return accounts
        .filter(a => a.type === 'Credit Card' && a.balance < 0)
        .reduce((acc, curr) => acc + Math.abs(curr.balance), 0);
  }, [accounts]);

  const stats = useMemo(() => {
    const currentMTDExpenses = transactions.filter(t => {
      const d = new Date(t.date);
      return t.type === TransactionType.EXPENSE && d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const currentMTDTotal = currentMTDExpenses.reduce((acc, t) => acc + t.amount, 0);
    const currentDay = today.getDate();
    const currentDailyAvg = currentMTDTotal / Math.max(currentDay, 1);

    return { currentDailyAvg };
  }, [transactions, currentMonth, currentYear]);

  const expenditureData = useMemo(() => {
    const expenses = transactions.filter(t => 
        t.type === TransactionType.EXPENSE && 
        new Date(t.date).getMonth() === currentMonth && 
        new Date(t.date).getFullYear() === currentYear
    );

    const total = expenses.reduce((acc, t) => acc + t.amount, 0);
    const catMap: Record<string, number> = {};

    expenses.forEach(t => {
        catMap[t.category] = (catMap[t.category] || 0) + t.amount;
    });

    const chartData = Object.entries(catMap)
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value);

    if (chartData.length === 0) {
        return { chartData: [], total: 0, isEmpty: true, topCategory: null };
    }

    return { chartData, total, isEmpty: false, topCategory: chartData[0] };
  }, [transactions, currentMonth, currentYear]);

  const lineChartData = useMemo(() => {
    const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const data = [];

    const getDailySpend = (month: number, year: number) => {
        const daily = new Array(32).fill(0);
        transactions.forEach(t => {
            const d = new Date(t.date);
            if (t.type === TransactionType.EXPENSE && d.getMonth() === month && d.getFullYear() === year) {
                daily[d.getDate()] += t.amount;
            }
        });
        for (let i = 1; i < daily.length; i++) daily[i] += daily[i-1];
        return daily;
    };

    const currentMonthData = getDailySpend(currentMonth, currentYear);
    let comparisonData: number[] = [];
    if (spendingComparison === 'year') {
        comparisonData = getDailySpend(currentMonth, currentYear - 1);
    } else {
        let prevMonth = currentMonth - 1;
        let prevYear = currentYear;
        if (prevMonth < 0) { prevMonth = 11; prevYear = currentYear - 1; }
        comparisonData = getDailySpend(prevMonth, prevYear);
    }

    for (let i = 1; i <= daysInCurrentMonth; i++) {
        data.push({
            day: i,
            ThisMonth: currentMonthData[i],
            Comparison: comparisonData[i] 
        });
    }
    return data;
  }, [transactions, currentMonth, currentYear, spendingComparison]);

  const recurringBills = useMemo(() => {
      const subs = transactions.filter(t => t.category === Category.SUBSCRIPTION);
      const unique = new Map();
      subs.forEach(t => {
          if (!unique.has(t.merchant)) unique.set(t.merchant, t);
      });
      return Array.from(unique.values()).slice(0, 5);
  }, [transactions]);

  const recentTransactions = useMemo(() => {
      return transactions.slice(0, 4);
  }, [transactions]);

  const goalMetrics = useMemo(() => {
      const limitVal = Number(spendingLimit);
      const safeLimit = !isNaN(limitVal) && limitVal > 0 ? limitVal : 1;
      const budgetUtilization = (currentPeriodSpend / safeLimit) * 100;

      const budgetProgress = budgets.map(b => {
          const spent = transactions
            .filter(t => t.category === b.category && t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth)
            .reduce((sum, t) => sum + t.amount, 0);
          return { ...b, spent, percentage: Math.min((spent / b.limit) * 100, 100) };
      });

      // Total Savings calculation
      const totalTarget = goals.reduce((acc, g) => acc + g.targetAmount, 0);
      const totalSaved = goals.reduce((acc, g) => acc + g.currentAmount, 0);
      const savingsProgress = totalTarget > 0 ? (totalSaved / totalTarget) * 100 : 0;

      return { budgetUtilization, budgetProgress, totalTarget, totalSaved, savingsProgress };
  }, [currentPeriodSpend, spendingLimit, budgets, transactions, currentMonth, goals]);

  const neuralCapacity = userPlan === 'ultra' ? 1500 : userPlan === 'pro' ? 50 : 3;
  const neuralRemaining = Math.max(0, neuralCapacity - insightUsage);
  const safeName = userName && userName.trim() !== '' ? userName : 'Pilot';
  const displayLimit = spendingLimit && !isNaN(Number(spendingLimit)) ? Number(spendingLimit) : 0;

  const handleProceedWithScan = () => {
    setShowScanConfirm(false);
    onNavigate('insights', { reportType: 'daily' });
  };

  return (
    <div className="pb-20 px-2 md:px-0">

        {/* Header */}
        <div className="mb-6 mt-2 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
                <h1 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight">Good {dayName}, {safeName}</h1>
                <div className="flex items-center gap-2 mt-1">
                    <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">
                        Last Updated: {lastUpdated}
                    </p>
                </div>
            </div>

            {onAddTransaction && (
                <button 
                    onClick={onAddTransaction}
                    className="hidden md:flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-3 rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 active:scale-95 transition-all group"
                >
                    <Plus className="w-4 h-4 group-hover:rotate-90 transition-transform" />
                    <span>Make New Transaction</span>
                </button>
            )}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

            {/* LEFT MAIN PANEL */}
            <div className="lg:col-span-8 flex flex-col gap-6 h-full">

                {/* 1. New Command Grid (Moved from right sidebar + consolidated stats) */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {/* Net Worth */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Wallet className="w-12 h-12 text-blue-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-blue-500/10"><Wallet className="w-4 h-4 text-blue-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Net Worth</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(netWorth)}</div>
                    </div>

                    {/* Credit Card */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><CreditCard className="w-12 h-12 text-rose-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-rose-500/10"><CreditCard className="w-4 h-4 text-rose-500" /></div>
                            <div className="flex flex-col">
                                <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Debt</span>
                            </div>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(creditCardDebt)}</div>
                    </div>

                    {/* Burn Rate */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Flame className="w-12 h-12 text-orange-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-orange-500/10"><Flame className="w-4 h-4 text-orange-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Daily Burn</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{formatCurrency(stats.currentDailyAvg)}</div>
                    </div>

                    {/* Neural Capacity */}
                    <div className="glass-card p-5 rounded-[2rem] border border-white/5 bg-[#0f172a]/60 flex flex-col justify-between h-32 relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Zap className="w-12 h-12 text-purple-500" /></div>
                        <div className="flex items-center gap-2 mb-2 relative z-10">
                            <div className="p-1.5 rounded-lg bg-purple-500/10"><Zap className="w-4 h-4 text-purple-500" /></div>
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Capacity</span>
                        </div>
                        <div className="text-2xl font-black text-white tracking-tight relative z-10">{neuralRemaining} <span className="text-sm text-slate-500 font-bold">OPS</span></div>
                    </div>
                </div>

                {/* 2. Spending chart */}
                <div className="glass-card p-6 md:p-8 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 backdrop-blur-xl relative overflow-hidden flex flex-col md:flex-row items-center gap-8 min-h-[300px]">
                    <div className="w-48 h-48 md:w-56 md:h-56 relative shrink-0 flex items-center justify-center">
                        {expenditureData.isEmpty ? (
                            <div className="text-center">
                                <div className="w-40 h-40 rounded-full border-2 border-dashed border-indigo-500/30 flex items-center justify-center animate-pulse">
                                    <PieChartIcon className="w-10 h-10 text-indigo-500/50" />
                                </div>
                            </div>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={expenditureData.chartData}
                                        cx="50%"
                                        cy="50%"
                                        innerRadius={60}
                                        outerRadius={90}
                                        paddingAngle={2}
                                        dataKey="value"
                                        stroke="none"
                                    >
                                        {expenditureData.chartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip 
                                        contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px', padding: '8px' }} 
                                        itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }} 
                                        formatter={(v: number) => formatCurrency(v)} 
                                    />
                                </PieChart>
                            </ResponsiveContainer>
                        )}
                    </div>

                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-start mb-6">
                            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <AlignLeft className="w-4 h-4 text-indigo-500" />
                                Spending chart
                            </h3>
                        </div>

                        {expenditureData.topCategory ? (
                            <div className="mb-6 p-4 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-between">
                                <div>
                                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Primary Drain</span>
                                    <span className="text-lg font-bold text-white">{expenditureData.topCategory.name}</span>
                                </div>
                                <div className="text-right">
                                    <span className="text-xl font-black text-white">{formatCurrency(expenditureData.topCategory.value)}</span>
                                    <span className="text-[10px] font-bold text-slate-400 block">{((expenditureData.topCategory.value / expenditureData.total) * 100).toFixed(1)}%</span>
                                </div>
                            </div>
                        ) : (
                            <div className="mb-6 p-6 rounded-2xl bg-slate-900/50 border border-white/5 flex flex-col justify-center items-start text-left">
                                <h4 className="text-white font-bold text-sm mb-1">Sensors Inactive</h4>
                                <p className="text-slate-500 text-xs font-medium mb-3">Log expense data to initialize topology map.</p>
                                <button onClick={onAddTransaction} className="text-indigo-400 font-bold text-xs uppercase tracking-widest hover:text-indigo-300 transition-colors flex items-center gap-1">
                                    Initialize <ChevronDown className="w-3 h-3 -rotate-90" />
                                </button>
                            </div>
                        )}

                        <div className="space-y-3">
                            {!expenditureData.isEmpty && expenditureData.chartData.slice(0, 3).map((item, i) => (
                                <div key={i} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                        <span className="text-xs font-bold text-slate-300 group-hover:text-white transition-colors">{item.name}</span>
                                    </div>
                                    <div className="h-1 flex-1 mx-4 bg-slate-800/50 rounded-full overflow-hidden">
                                        <div className="h-full rounded-full transition-all duration-1000" style={{ width: `${(item.value / expenditureData.total) * 60}%`, backgroundColor: COLORS[i % COLORS.length], opacity: 0.6 }}></div>
                                    </div>
                                    <span className="text-[10px] font-bold text-slate-500">MTD</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* 3. Full Width Transactions */}
                <div className="glass-card rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 p-6 overflow-hidden flex flex-col">
                    <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4">My Recent Transactions</h3>
                    <div className="flex-1 w-full">
                        {recentTransactions.length > 0 ? (
                            <table className="w-full text-left border-collapse">
                                <thead className="text-[9px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5">
                                    <tr>
                                        <th className="py-2">Date</th>
                                        <th className="py-2">Name</th>
                                        <th className="py-2 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="text-xs font-bold text-slate-300">
                                    {recentTransactions.map((t) => (
                                        <tr key={t.id} className="border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                            <td className="py-4 text-slate-500 font-mono text-[10px]">{new Date(t.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }).toUpperCase()}</td>
                                            <td className="py-4">{t.merchant}</td>
                                            <td className={`py-4 text-right ${t.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>{formatCurrency(t.amount)}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center p-6 bg-slate-900/30 rounded-2xl border-2 border-dashed border-white/5">
                                <div className="w-12 h-12 bg-slate-800 rounded-full flex items-center justify-center mb-3">
                                    <Rocket className="w-6 h-6 text-indigo-400" />
                                </div>
                                <h4 className="text-white font-bold text-sm">Mission: First Log</h4>
                                <p className="text-slate-500 text-[10px] uppercase tracking-wider mb-4">Ledger is empty.</p>
                                <button onClick={onAddTransaction} className="px-4 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase tracking-widest rounded-lg shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                                    Record Event
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                {/* 4. Spending Graph */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-[#0f172a]/60 flex-1 min-h-[18rem] flex flex-col overflow-hidden">
                    <div className="flex justify-between items-center mb-2 shrink-0">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending Velocity</h3>
                        <div className="relative">
                            <button 
                                onClick={(e) => toggleMenu(e, 'spending_menu')}
                                className="flex items-center gap-2 border border-white/10 rounded px-3 py-1.5 bg-slate-900 cursor-pointer hover:bg-slate-800 transition-colors"
                            >
                                <span className="text-[10px] font-bold text-slate-400 uppercase">
                                    Vs {spendingComparison === 'year' ? 'Last Year' : 'Last Month'}
                                </span>
                                <ChevronDown className="w-3 h-3 text-slate-500" />
                            </button>
                            {activeMenu === 'spending_menu' && (
                                <div className="absolute right-0 top-full mt-2 w-40 bg-slate-900 border border-white/10 rounded-xl shadow-xl z-20 overflow-hidden animate-fade-in">
                                    <button onClick={() => { setSpendingComparison('year'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Year</button>
                                    <button onClick={() => { setSpendingComparison('month'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Month</button>
                                </div>
                            )}
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <ComposedChart data={lineChartData} margin={{ top: 5, right: 10, left: -20, bottom: 20 }}>
                                <defs>
                                    <linearGradient id="colorThisMonth" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4}/>
                                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <XAxis 
                                    dataKey="day" 
                                    stroke="#475569" 
                                    fontSize={10} 
                                    tickLine={false} 
                                    axisLine={false} 
                                    dy={10}
                                />
                                <YAxis 
                                    stroke="#475569" 
                                    fontSize={10} 
                                    tickLine={false} 
                                    axisLine={false} 
                                    tickFormatter={(val) => isPrivacyMode ? '•••' : `$${val > 999 ? (val/1000).toFixed(1) + 'k' : val}`}
                                />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.5)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#fff' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="Comparison" stroke="#334155" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Area type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorThisMonth)" />
                            </ComposedChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-1 shrink-0 pb-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-700"></div>
                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{spendingComparison === 'year' ? 'Last Year' : 'Last Month'}</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_#6366f1]"></div>
                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR */}
            <div className="lg:col-span-4 flex flex-col gap-6 h-full">

                {/* Goal Vector - Card theme RED, Button theme INDIGO (Default Nova) */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex flex-col gap-6">
                    <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-rose-500/20 flex items-center justify-center border border-rose-500/30">
                                <Target className="w-5 h-5 text-rose-400" />
                            </div>
                            <div>
                                <h3 className="text-sm font-black text-white uppercase tracking-wider">Goal Vector</h3>
                                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Financial Velocity</p>
                            </div>
                        </div>
                        {onAddTransaction && (
                            <button 
                                onClick={onAddTransaction}
                                className="w-8 h-8 flex items-center justify-center rounded-xl bg-slate-800 hover:bg-rose-600 border border-white/5 hover:border-rose-500/50 text-slate-400 hover:text-white transition-all shadow-lg active:scale-95 group"
                                title="Add Transaction"
                            >
                                <Plus className="w-4 h-4" />
                            </button>
                        )}
                    </div>

                    <div className="space-y-5 max-h-60 overflow-y-auto custom-scrollbar pr-1">
                        <div>
                            {/* Global Monthly Limit */}
                            <div className="flex justify-between items-end mb-2">
                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Global Limit</span>
                                <span className="text-[10px] font-black text-amber-400">
                                    {formatCurrency(currentPeriodSpend)} <span className="text-slate-600">/ {formatCurrency(displayLimit)}</span>
                                </span>
                            </div>
                            <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ${goalMetrics.budgetUtilization > 100 ? 'bg-rose-500' : 'bg-gradient-to-r from-amber-400 to-orange-500'}`}
                                    style={{ width: `${Math.min(goalMetrics.budgetUtilization, 100)}%` }}
                                ></div>
                            </div>
                        </div>

                        {/* Category Limits */}
                        {goalMetrics.budgetProgress.length > 0 && (
                            <div className="space-y-3 pt-2">
                                {goalMetrics.budgetProgress.map(b => (
                                    <div key={b.id}>
                                        <div className="flex justify-between items-end mb-1">
                                            <span className="text-[9px] font-bold text-slate-500 uppercase tracking-wider truncate max-w-[100px]">{b.category}</span>
                                            <span className={`text-[9px] font-black ${b.spent > b.limit ? 'text-rose-400' : 'text-slate-300'}`}>
                                                {formatCurrency(b.spent)} / {formatCurrency(b.limit)}
                                            </span>
                                        </div>
                                        <div className="h-1 w-full bg-slate-800 rounded-full overflow-hidden">
                                            <div 
                                                className={`h-full rounded-full transition-all duration-1000 ${b.spent > b.limit ? 'bg-rose-500' : 'bg-indigo-500'}`}
                                                style={{ width: `${Math.min((b.spent / b.limit) * 100, 100)}%` }}
                                            ></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* Total Savings Tracker */}
                        {goalMetrics.totalTarget > 0 ? (
                            <div>
                                <div className="flex justify-between items-end mb-2">
                                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Total Savings</span>
                                    <span className="text-[10px] font-black text-emerald-400">
                                        {formatCurrency(goalMetrics.totalSaved)} <span className="text-slate-600">/ {formatCurrency(goalMetrics.totalTarget)}</span>
                                    </span>
                                </div>
                                <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                    <div 
                                        className="h-full rounded-full transition-all duration-1000 bg-gradient-to-r from-emerald-500 to-teal-400"
                                        style={{ width: `${Math.min(goalMetrics.savingsProgress, 100)}%` }}
                                    ></div>
                                </div>
                            </div>
                        ) : null}

                        {/* Individual Savings Goals */}
                        {goals.length > 0 && (
                            <>
                                <div className="h-px bg-white/5 my-2"></div>
                                <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest block mb-2 opacity-80">Active Goals</span>
                                {goals.map(goal => {
                                    const progress = Math.min((goal.currentAmount / goal.targetAmount) * 100, 100);
                                    return (
                                        <div key={goal.id}>
                                            <div className="flex justify-between items-end mb-1">
                                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider truncate max-w-[120px]">{goal.name}</span>
                                                <span className="text-[9px] font-black text-emerald-400">
                                                    {formatCurrency(goal.currentAmount)}
                                                </span>
                                            </div>
                                            <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden border border-white/5">
                                                <div 
                                                    className={`h-full rounded-full transition-all duration-1000 bg-gradient-to-r ${goal.color}`} 
                                                    style={{ width: `${progress}%` }}
                                                ></div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </>
                        )}

                        {goalMetrics.budgetProgress.length === 0 && goalMetrics.totalTarget === 0 && (
                            <div className="p-4 bg-slate-900/50 rounded-xl border border-white/5 text-center flex flex-col items-center">
                                <span className="text-[10px] text-slate-500 font-bold uppercase tracking-wide mb-2">No active targets</span>
                                {onAddGoal && (
                                    <button onClick={onAddGoal} className="text-emerald-400 font-black text-[9px] uppercase tracking-widest bg-emerald-500/10 px-3 py-1.5 rounded border border-emerald-500/20 hover:bg-emerald-500/20 transition-colors">
                                        + Set Goal
                                    </button>
                                )}
                            </div>
                        )}
                    </div>

                    <button 
                        onClick={() => onNavigate('smart_money', { tab: 'sandbox' })}
                        className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 active:scale-95 transition-all flex items-center justify-center gap-2 mt-auto shrink-0"
                    >
                        <Microscope className="w-3.5 h-3.5" /> Simulate My Goal
                    </button>
                </div>

                {/* Actions List */}
                <div className="space-y-3">
                    <div className="relative">
                        <button 
                            onClick={(e) => toggleMenu(e, 'overview_menu')}
                            className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors"
                        >
                            Financial Overview <ChevronDown className="w-4 h-4 text-slate-500" />
                        </button>
                        {activeMenu === 'overview_menu' && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-slate-950 border border-white/10 rounded-2xl shadow-xl z-30 overflow-hidden animate-fade-in p-1">
                                <button onClick={() => { onNavigate('insights', { reportType: 'monthly' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <FileText className="w-3 h-3 text-emerald-400" /> Generate Monthly Report
                                </button>
                                <button onClick={() => { onAskCoach && onAskCoach(""); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <UserCircle className="w-3 h-3 text-indigo-400" /> Question Supervisor
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="relative">
                        <button 
                            onClick={(e) => toggleMenu(e, 'tools_menu')}
                            className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors"
                        >
                            Smart Money Tools <ChevronDown className="w-4 h-4 text-slate-500" />
                        </button>
                        {activeMenu === 'tools_menu' && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-slate-950 border border-white/10 rounded-2xl shadow-xl z-30 overflow-hidden animate-fade-in p-1">
                                <button onClick={() => { onNavigate('smart_money', { tab: 'cashflow' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <GitFork className="w-3 h-3 text-indigo-400" /> Cashflow Beta
                                </button>
                                <button onClick={() => { onNavigate('smart_money', { tab: 'sandbox' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <Microscope className="w-3 h-3 text-amber-400" /> Predictive Sandbox
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <button onClick={() => onNavigate('smart_money', { tab: 'negotiator' })} className="p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-800 transition-colors text-center">
                            Negotiate My Bill
                        </button>
                        <button onClick={() => onNavigate('insights', { reportType: 'daily' })} className="p-4 bg-indigo-600 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 transition-colors text-center border border-indigo-500/50">
                            Summarize Action For Today
                        </button>
                    </div>
                    <button onClick={() => onNavigate('investment')} className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors">
                        Investment Node <ChevronDown className="w-4 h-4 text-slate-500" />
                    </button>
                </div>

                {/* Recurring Bills */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex-1 min-h-[260px] flex flex-col">
                    <div className="flex justify-between items-center mb-4 shrink-0">
                        <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">My Recurring Bill</h3>
                        <span className="px-2 py-1 rounded bg-slate-950 border border-white/5 text-[8px] font-bold text-slate-500 uppercase">MTD</span>
                    </div>
                    <div className="space-y-3 overflow-y-auto custom-scrollbar flex-1 pr-1">
                        {recurringBills.length > 0 ? (
                            recurringBills.map(bill => (
                                <div key={bill.id} className="flex items-center gap-3 group">
                                    <div className={`w-7 h-7 rounded-full flex items-center justify-center text-[9px] font-black text-white ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-800'}`}>
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 flex justify-between items-center">
                                        <span className="text-[11px] font-bold text-slate-300 group-hover:text-white transition-colors truncate max-w-[100px]">{bill.merchant}</span>
                                        <span className="text-[11px] font-bold text-slate-500">{formatCurrency(bill.amount)}/mo</span>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full opacity-50 pb-2">
                                <div className="p-2 bg-slate-800 rounded-full mb-1">
                                    <FileText className="w-4 h-4 text-slate-500" />
                                </div>
                                <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">No subscriptions found</span>
                            </div>
                        )}
                    </div>
                </div>

            </div>
        </div>

        {/* Scan Confirmation Modal */}
        {showScanConfirm && (
            <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
                <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-sm p-8 shadow-2xl relative animate-slide-up">
                    <div className="w-16 h-16 bg-indigo-500/20 rounded-2xl flex items-center justify-center mx-auto mb-6 border border-indigo-500/30">
                        <Zap className="w-8 h-8 text-indigo-400 animate-pulse" />
                    </div>
                    <h3 className="text-xl font-black text-white mb-2 text-center uppercase tracking-tight">Initialize Audit?</h3>
                    <p className="text-sm text-slate-400 mb-8 text-center leading-relaxed">This will execute a full neural scan of your capital vectors to provide strategic intelligence. <br/><span className="text-indigo-400 font-bold">1 Token will be utilized.</span></p>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => setShowScanConfirm(false)} className="py-4 bg-slate-800 text-slate-400 font-black rounded-xl text-[10px] uppercase tracking-widest hover:text-white transition-colors">Abort</button>
                        <button onClick={handleProceedWithScan} className="py-4 bg-indigo-600 text-white font-black rounded-xl text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 transition-all flex items-center justify-center gap-2">
                            <Check className="w-4 h-4" /> Proceed
                        </button>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default Dashboard;
